var e={studyTitle:`Hướng dẫn tu học Phật pháp`,studyDescription:`Lộ trình cho người mới, tụng kinh, trì chú và thực hành mỗi ngày`,appTitle:`Hướng dẫn sử dụng ứng dụng`,appDescription:`Đọc sách, nghe pháp, công cụ tu tập, tài khoản và đồng bộ`},t={studyTitle:`Buddhist practice guide`,studyDescription:`Getting started, sutra recitation, mantras and daily practice`,appTitle:`App user guide`,appDescription:`Reading, Dharma talks, practice tools, accounts and sync`};function n(n){return n?t:e}var r=[{id:`huong-dan-nguoi-moi`,icon:`🌱`,title:`Hướng dẫn cho người mới tìm hiểu Phật pháp và tu tập`,shortTitle:`Người Mới`,keywords:[`người mới`,`mới tìm hiểu`,`bắt đầu tu tập`,`lộ trình tu tập`,`báo ứng hiện đời`,`sứ mệnh độ vong`,`chú đại bi`,`trì tụng`,`mục tu tập`,`giảng kinh địa tạng`,`tuyên hóa`,`giảng kinh pháp hoa`,`kinh pháp hoa`,`tụng kinh địa tạng`,`niệm a di đà phật`,`niệm phật`,`công phu`,`nhân quả`,`luân hồi`],editorialStatus:`verified`,introduction:[`Bước đầu tìm hiểu đạo Phật và thực hành tu tập có thể khiến nhiều bạn băn khoăn trước vô vàn kinh điển, sách vở và phương pháp khác nhau. Một lộ trình tu học tuần tự, đúng chánh pháp sẽ giúp bạn xây dựng chánh tín kiên cố, tiêu trừ nghiệp chướng và gặt hái an lạc thiết thực ngay trong đời sống hiện tại.`,`Dưới đây là lộ trình 4 giai đoạn căn bản và vững chắc nhất dành cho người mới: từ việc đọc sách thấu suốt nhân quả, bước vào thực hành trì chú mỗi ngày, nâng cao chánh tri kiến qua lời giảng kinh của chư Tổ, đến định hình pháp môn chuyên tu bền bỉ phù hợp với công phu của bản thân.`],topics:[{id:`giai-doan-1-doc-sach-nhan-qua-luan-hoi`,title:`Giai đoạn 1 — Đọc các cuốn sách về Nhân Quả & Luân Hồi thực tế`,keywords:[`giai đoạn 1`,`đọc sách`,`báo ứng hiện đời`,`sứ mệnh độ vong`,`địa ngục du ký`,`luân hồi du ký`,`ngọc lịch bửu phiêu`,`an sỹ toàn thư`,`nhân quả`,`luân hồi`,`chánh tín`,`quả khanh`],blocks:[{type:`callout`,tone:`note`,title:`Nền tảng đầu tiên: Xây dựng Chánh Tín vào Luật Nhân Quả`,text:`Phật dạy: “Muốn biết nhân đời trước, hãy xem quả thọ nhận đời này; muốn biết quả đời sau, hãy xem nhân gieo đời này”. Đối với người mới tìm hiểu Phật pháp, điều quan trọng nhất chưa phải là đi vào triết lý cao siêu, mà là đọc và chứng nghiệm các câu chuyện nhân quả có thật ở thời hiện đại để phát khởi niềm tin sâu sắc vào luật luân hồi nghiệp báo, từ đó tự giác đoạn trừ việc ác, tích cực làm việc lành.`},{type:`steps`,items:[{title:`Đọc trọn bộ “Báo Ứng Hiện Đời” (Tập 1 đến Tập 8)`,text:`Bộ sách kinh điển do cư sĩ Quả Khanh thuật lại dưới sự chứng minh của Hòa thượng Diệu Pháp (Trung Quốc). Các câu chuyện đều là người thật việc thật thời hiện đại: nguồn cơn của các chứng bệnh nan y hiểm nghèo, gia đạo trắc trở, con cái ngỗ nghịch, kinh doanh phá sản... đều truy nguyên từ nghiệp sát sinh, phá thai, tà dâm, trộm cắp hay bất hiếu. Đọc để rúng động tâm can và dứt khoát dừng tạo ác nghiệp.`},{title:`Đọc cuốn “Sứ Mệnh Độ Vong”`,text:`Tác phẩm mở ra cái nhìn sáng tỏ, giàu lòng từ bi về thế giới cõi âm và tâm thức sau khi lìa trần. Bạn sẽ hiểu rõ nỗi đau đớn, quạnh quẽ của các vong linh thai nhi, oan gia trái chủ và sự trông ngóng phước lành từ người thân. Sách giúp người đọc không còn sợ hãi vô căn cứ hay sa vào mê tín cúng bái bùa ngải, mà hiểu rằng chỉ có tâm từ bi, tụng kinh, niệm Phật và hồi hướng phước đức chân thật mới hóa giải oán hận, giúp các hương linh được siêu sinh.`},{title:`Đọc tác phẩm “An Sỹ Toàn Thư” (Quyển Thượng & Quyển Hạ)`,text:`Bộ kỳ thư khuyến thiện bậc nhất của cư sĩ Chu An Sỹ, được Đại sư Ấn Quang hết lời tán thán và xem là bảo bối răn dạy đạo đức nhân quả. Tác phẩm làm sáng tỏ nguồn gốc phúc họa, khuyên người tích đức hành thiện, giữ gìn giới hạnh và đoạn trừ việc ác từ trong ý niệm, đặt nền tảng chánh tín kiên cố cho bước đường tu học.`},{title:`Kết hợp nghe Pháp thoại: “Cô Ba Cháo Gà du Địa ngục”, “Địa Ngục Du Ký”, “Luân Hồi Du Ký”, “Ngọc Lịch Bửu Phiêu”`,text:`Bên cạnh việc đọc sách, bạn hãy tận dụng thời gian rảnh rỗi khi làm việc nhà, lái xe hoặc đi bộ để nghe các bài Pháp thoại và câu chuyện nhân quả trên mục Pháp Thoại. Tiêu biểu như câu chuyện cận tử rúng động “Cô Ba Cháo Gà du Địa ngục”, tác phẩm “Địa Ngục Du Ký”, “Luân Hồi Du Ký” và pho sách cổ khuyến thiện “Ngọc Lịch Bửu Phiêu” ghi chép tường tận cảnh giới Thập Điện Diêm Vương và quả báo tội phước, giúp củng cố niềm tin vững chắc vào cõi vô hình và luật nhân quả.`}]},{type:`bullets`,title:`Mục tiêu hoàn thành sau Giai đoạn 1:`,items:[`Dứt hẳn mối hoài nghi về cõi vô hình và luật nhân quả luân hồi.`,`Chủ động ăn chay, giảm sát sinh, phóng sinh cứu vật, hiếu thảo với cha mẹ và nói lời hòa ái.`,`Ý thức sâu sắc rằng đời người ngắn ngủi, vô thường nhanh chóng để phát tâm tha thiết tu tập.`]},{type:`link`,href:`/?sach=bao-ung-hien-doi&q=Báo+Ứng+Hiện+Đời`,label:`Sách: Trọn bộ “Báo Ứng Hiện Đời” (Cư sĩ Quả Khanh)`,text:`Đọc những câu chuyện nhân quả có thật thời hiện đại để thấu hiểu căn nguyên của bệnh tật, tai ương và đoạn trừ việc ác.`,buttonLabel:`Đọc sách`},{type:`link`,href:`/?sach=su-menh-do-vong&q=Sứ+Mệnh+Độ+Vong`,label:`Sách: “Sứ Mệnh Độ Vong”`,text:`Mở rộng cái nhìn từ bi về thế giới cõi âm, vong linh thai nhi và cách hồi hướng phước đức chân thật.`,buttonLabel:`Đọc sách`},{type:`link`,href:`/?sach=an-sy-toan-thu&q=An+Sỹ+Toàn+Thư`,label:`Sách: Tác phẩm “An Sỹ Toàn Thư” (Quyển Thượng & Quyển Hạ)`,text:`Bộ kỳ thư khuyến thiện bậc nhất phân tích tường tận luật nhân quả, khuyên người bỏ ác làm lành và tích lũy âm đức sâu dày.`,buttonLabel:`Đọc sách`},{type:`link`,href:`/phap-thoai?album=co-ba-chao-ga&q=Cô+Ba+Cháo+Gà`,label:`Pháp Thoại: “Cô Ba Cháo Gà du Địa ngục”`,text:`Nghe câu chuyện cận tử ly kỳ và chân thật của Cô Ba Cháo Gà kể lại hành trình du Thập Điện Diêm Vương và quả báo thiện ác.`,buttonLabel:`Nghe pháp thoại`},{type:`link`,href:`/phap-thoai?q=Địa+Ngục+Du+Ký`,label:`Pháp Thoại: “Địa Ngục Du Ký” & “Luân Hồi Du Ký”`,text:`Nghe các bài giảng âm thanh và câu chuyện cảnh tỉnh nghiệp báo luân hồi trong mục Pháp Thoại.`,buttonLabel:`Nghe pháp thoại`},{type:`link`,href:`/?sach=ngoc-lich-buu-phieu&q=Ngọc+Lịch+Bửu+Phiêu`,label:`Sách & Pháp Thoại: “Ngọc Lịch Bửu Phiêu”`,text:`Tác phẩm khuyến thiện kinh điển ghi chép cảnh giới quả báo thiện ác và con đường cải mệnh tích đức.`,buttonLabel:`Xem sách`}]},{id:`giai-doan-2-hang-ngay-tri-tung-chu-dai-bi`,title:`Giai đoạn 2 — Hằng ngày trì tụng Chú Đại Bi & Nghe Pháp thoại giảng kinh Địa Tạng`,keywords:[`giai đoạn 2`,`hằng ngày`,`trì tụng`,`chú đại bi`,`mục tu tập`,`tiêu trừ nghiệp chướng`,`quán thế âm`,`chuông mõ`,`chuỗi hạt`,`bảo hộ thân tâm`,`nghe pháp thoại`,`giảng kinh địa tạng`,`tuyên hóa`],blocks:[{type:`callout`,tone:`note`,title:`Khởi đầu công phu thực tế: Nương tựa oai lực Thần Chú Đại Bi`,text:`Thần Chú Đại Bi (Đại Bi Tâm Đà-ra-ni) là tâm chú vi diệu của Đức Bồ Tát Quán Thế Âm, có oai lực tiêu trừ vô lượng ác nghiệp, hóa giải oan trái và hộ trì thân tâm vô cùng thù thắng. Đối với người mới, trì tụng Chú Đại Bi giúp tâm thức nhanh chóng được lắng dịu, xua tan nỗi sợ hãi, lo âu và mang lại cảm giác bình an sâu sắc trong đời sống hằng ngày.`},{type:`steps`,items:[{title:`Mở mục “Tu Tập” trên website hoặc ứng dụng`,text:`Truy cập mục Tu Tập trên thanh điều hướng, chọn bài “Chú Đại Bi”. Ứng dụng tích hợp sẵn âm thanh chuông mõ gõ nhịp giữ tâm định, chế độ tự động cuộn chữ, giao diện toàn màn hình không phân tâm và chuỗi hạt điện tử để đếm số biến đã trì.`},{title:`Thiết lập thời khóa đều đặn mỗi ngày`,text:`Nên dành ra 15 – 30 phút mỗi ngày vào buổi sáng sớm hoặc buổi tối trước khi đi ngủ. Mới bắt đầu bạn có thể trì từ 3 đến 7 biến; khi đã quen và thuộc dần câu chữ thì tăng lên 21 biến, 49 biến hoặc 108 biến mỗi ngày tùy theo điều kiện thời gian.`},{title:`Học thuộc lòng để trì tụng mọi lúc mọi nơi`,text:`Hãy nỗ lực đọc đều đặn để thuộc lòng Chú Đại Bi. Khi đã thuộc làu, bạn có thể trì thầm trong tâm khi đi bộ, đi xe buýt, dọn dẹp nhà cửa hay nấu ăn. Giữ tâm luôn gắn với câu thần chú sẽ giúp đoạn dứt các suy nghĩ lăng xăng, đồng thời phóng tỏa năng lượng từ bi gieo duyên lành cho muôn loài xung quanh.`},{title:`Kết hợp vừa đọc vừa nghe Pháp thoại giảng Kinh Địa Tạng của HT. Tuyên Hóa`,text:`Trong giai đoạn này, bạn có thể kết hợp song song giữa việc trì chú và mở nghe Pháp thoại giảng kinh Địa Tạng của Hòa thượng Tuyên Hóa (bộ Kinh Địa Tạng Giảng Thuật / Thiển Thích có sẵn trong mục Pháp Thoại). Vừa đọc vừa nghe giảng giải sẽ giúp tâm trí sáng tỏ, thẩm thấu sâu sắc tinh thần hiếu đạo và đại nguyện của Bồ Tát Địa Tạng, tạo nền móng vững chắc cho công phu hằng ngày.`}]},{type:`bullets`,title:`Quy tắc căn bản khi trì tụng Chú Đại Bi:`,items:[`Trước khi tụng: súc miệng, rửa tay sạch sẽ, y phục trang nhã và kín đáo.`,`Khi tụng: giữ tâm thành kính, đọc rõ từng âm chữ, không cần chạy theo tốc độ mà cần nhiếp tâm trọn vẹn.`,`Sau khi tụng xong: luôn nhớ phát nguyện đọc bài Hồi Hướng để chia sẻ công đức lành cho cửu huyền thất tổ, oan gia trái chủ và khắp pháp giới chúng sinh.`]},{type:`link`,href:`/tu-tap?article=chu-dai-bi&mode=practice`,label:`Trang Tu Tập — Vào thẳng khóa trì tụng Chú Đại Bi`,text:`Mở trực tiếp chế độ tu tập Chú Đại Bi toàn màn hình kèm âm thanh chuông mõ tự động và chuỗi hạt điện tử đếm biến.`,buttonLabel:`Vào tu tập Chú Đại Bi`},{type:`link`,href:`/phap-thoai?album=kinh-dia-tang-tuyen-hoa&q=Địa+Tạng+Tuyên+Hóa`,label:`Pháp Thoại: Kinh Địa Tạng Giảng Thuật (HT. Tuyên Hóa)`,text:`Nghe trọn bộ bài giảng khẩu truyền của Đại Lão Hòa Thượng Tuyên Hóa về Kinh Địa Tạng Bồ Tát Bổn Nguyện.`,buttonLabel:`Nghe pháp thoại`},{type:`link`,href:`/phap-thoai?album=chu-dai-bi-tuyen-hoa&q=Chú+Đại+Bi+Tuyên+Hóa`,label:`Pháp Thoại: Chú Đại Bi Giảng Giải (HT. Tuyên Hóa)`,text:`Lắng nghe từng câu chú được giảng giải chi tiết về công hạnh, oai thần hộ trì và phương pháp trì tụng hiệu nghiệm.`,buttonLabel:`Nghe pháp thoại`}]},{id:`giai-doan-3-doc-giang-kinh-dia-tang-va-phap-hoa`,title:`Giai đoạn 3 — Đọc & Nghe giảng kinh Địa Tạng, giảng kinh Pháp Hoa (HT. Tuyên Hóa)`,keywords:[`giai đoạn 3`,`kinh địa tạng`,`kinh pháp hoa`,`tuyên hóa`,`thiển thích`,`giảng giải`,`giảng kinh pháp hoa`,`chánh tri kiến`,`đại thừa`,`khai thị`,`hiếu đạo`,`phật tánh`,`nghe pháp thoại`],blocks:[{type:`callout`,tone:`note`,title:`Mở rộng Chánh Tri Kiến: Hiểu sâu lời Phật dạy qua lời giảng của Chư Tổ`,text:`Khi việc trì tụng Chú Đại Bi đã thành thói quen và tâm bạn bắt đầu an định, bước tiếp theo là bồi đắp trí tuệ giải thoát. Việc đọc kinh điển Đại Thừa kèm theo lời giảng giải (thiển thích) bình dị, sâu sắc của bậc cao tăng đắc đạo như Hòa thượng Tuyên Hóa sẽ giúp bạn thấu suốt nghĩa lý chân thật của Phật đà, có được chánh tri kiến vững vàng và không bị lạc vào tà kiến mê tín.`},{type:`steps`,items:[{title:`Đọc & Nghe “Kinh Địa Tạng Bồ Tát Bổn Nguyện Thiển Thích” (HT. Tuyên Hóa giảng giải)`,text:`Kinh Địa Tạng được tôn xưng là “Kinh Hiếu Đạo” của Phật giáo. Lời giảng giải hóm hỉnh, giản dị mà đầy trí huệ của Sư Phụ Tuyên Hóa giúp bạn hiểu tận gốc nguyên nhân đọa vào tam đồ ác đạo, các hình phạt ở địa ngục, lòng hiếu thảo tột cùng của Bồ Tát Địa Tạng khi còn là Quang Mục hay Bà-la-môn nữ, cùng phương pháp tụng kinh cúng dường sao cho cha mẹ hiện tiền tăng phước thọ, tổ tiên quá vãng được siêu sinh. Bạn có thể vừa đọc sách trên website, vừa nghe trọn bộ audio trong mục Pháp Thoại.`},{title:`Đọc & Nghe “Diệu Pháp Liên Hoa Kinh Thiển Thích” (Kinh Pháp Hoa — HT. Tuyên Hóa)`,text:`Kinh Pháp Hoa là bộ kinh Tối Thượng Thừa, được tôn xưng là “Vua của các kinh”, chứa đựng tư tưởng rốt ráo nhất: “Khai thị ngộ nhập tri kiến Phật” và khẳng định mọi chúng sinh đều có Phật tánh bình đẳng, tương lai đều sẽ thành Phật. Lời giảng của HT. Tuyên Hóa khai mở dung lượng tâm bao la, giúp người tu phá vỡ tâm hẹp hòi phân biệt, vượt lên mọi đối đãi hơn thua của cuộc đời.`},{title:`Đọc thêm các bộ “Khai Thị” và “Pháp Ngữ” của HT. Tuyên Hóa`,text:`Đọc thêm 6 quyển Khai Thị và tuyển tập Pháp Ngữ của Hòa thượng để học hỏi cách đối nhân xử thế, giữ gìn tịnh giới, làm chủ ngũ dục (tài, sắc, danh, thực, thùy) và nhận diện rõ các cạm bẫy tâm lý, chướng ngại ma sự trong thời mạt pháp.`}]},{type:`bullets`,title:`Lợi ích cốt lõi khi đọc kinh có giảng giải:`,items:[`Tránh đọc tụng theo kiểu hình thức mà không hiểu lời dạy thâm sâu của Đức Phật.`,`Xây dựng hệ thống tri kiến Phật pháp chuẩn mực, biết phân biệt rõ chánh pháp và tà giáo.`,`Khơi dậy tâm Bồ Đề rộng lớn: tu tập không chỉ cầu bình an ích kỷ cho bản thân mà còn vì lợi lạc của gia đình và cộng đồng.`]},{type:`link`,href:`/?sach=dia-tang&q=Kinh+Địa+Tạng+Thiển+Thích`,label:`Sách: Kinh Địa Tạng Bồ Tát Bổn Nguyện Thiển Thích (HT. Tuyên Hóa)`,text:`Đọc trọn vẹn bộ sách giảng giải tường tận từng phẩm kinh Địa Tạng của HT. Tuyên Hóa trong thư viện sách.`,buttonLabel:`Đọc sách`},{type:`link`,href:`/?sach=phap-hoa&q=Pháp+Hoa`,label:`Sách: Diệu Pháp Liên Hoa Kinh Thiển Thích (Kinh Pháp Hoa — HT. Tuyên Hóa)`,text:`Đọc bộ kinh Tối Thượng Thừa khai mở Phật tri kiến và nhận ra Phật tánh bình đẳng sẵn có nơi muôn loài.`,buttonLabel:`Đọc sách`},{type:`link`,href:`/?sach=khai-thi&q=Khai+Thị`,label:`Sách: Tuyển tập Khai Thị & Pháp Ngữ (HT. Tuyên Hóa)`,text:`Đọc những bài khai thị thực tế, gần gũi chỉ dẫn cách giữ tịnh giới, làm chủ tâm ý và vượt qua nghịch cảnh đời thường.`,buttonLabel:`Đọc sách`},{type:`link`,href:`/phap-thoai?album=phap-hoa-tuyen-hoa&q=Pháp+Hoa+Tuyên+Hóa`,label:`Pháp Thoại: Giảng Giải Kinh Pháp Hoa (HT. Tuyên Hóa)`,text:`Nghe âm thanh toàn bộ bài giảng Kinh Diệu Pháp Liên Hoa của HT. Tuyên Hóa trên chuyên mục Pháp Thoại.`,buttonLabel:`Nghe pháp thoại`}]},{id:`giai-doan-4-dinh-hinh-phap-mon-chuyen-tu`,title:`Giai đoạn 4 — Định hình pháp môn chuyên tu: Tụng Kinh Địa Tạng hoặc Niệm Phật tùy công phu`,keywords:[`giai đoạn 4`,`pháp môn chuyên tu`,`tụng kinh địa tạng`,`niệm a di đà phật`,`niệm phật`,`tùy công phu`,`tịnh độ`,`vãng sanh`,`chánh trợ song hành`,`hồi hướng`],blocks:[{type:`callout`,tone:`note`,title:`Lựa chọn pháp môn hành trì phù hợp với căn duyên và thời lượng công phu`,text:`Sau khi đã thấu hiểu luật nhân quả, quen với nhịp trì chú hằng ngày và được khai sáng tri kiến qua lời giảng kinh của Hòa thượng Tuyên Hóa, bạn đã có một nền tảng tu học vô cùng vững chãi. Ở giai đoạn này, bạn hãy căn cứ vào thời gian biểu, hoàn cảnh sinh hoạt và tâm nguyện của mình để định hình pháp môn chuyên tu lâu dài.`},{type:`cards`,items:[{title:`Hướng 1: Chuyên trì tụng Kinh Địa Tạng Bồ Tát Bổn Nguyện`,text:`Rất phù hợp cho người có thời gian ngồi tụng từ 45 đến 90 phút mỗi ngày; người đang gặp nhiều bế tắc, đau ốm, gia đạo lộn xộn; hoặc có tâm nguyện tha thiết muốn giải nghiệp chướng nhiều kiếp và báo hiếu cửu huyền thất tổ. Bạn có thể tụng trọn 1 bộ kinh (13 phẩm) mỗi ngày, hoặc chia làm 3 ngày (mỗi ngày tụng 1 quyển Thượng, Trung hoặc Hạ). Kiên trì tụng đủ 21, 49 hoặc 100 biến sẽ cảm nhận rõ rệt sự chuyển hóa nghiệp duyên và an ổn gia đạo.`},{title:`Hướng 2: Chuyên tâm niệm “Nam Mô A Di Đà Phật” (Pháp môn Tịnh Độ)`,text:`Pháp môn vĩ đại, bình dị mà rốt ráo nhất trong thời mạt pháp, phù hợp cho mọi lứa tuổi, từ người bận rộn công việc đến người già yếu. Phát nguyện mỗi ngày niệm từ 1.000 đến 10.000 câu Phật hiệu bằng chuỗi hạt, đi đứng nằm ngồi đều thầm nhớ Phật niệm Phật. Mục tiêu tối hậu là nương nhờ đại nguyện của Phật A Di Đà để vãng sanh về cõi Tây Phương Cực Lạc giải thoát sinh tử luân hồi. Chỉ cần đầy đủ Tín - Hạnh - Nguyện sâu xa thì muôn người tu muôn người thành tựu.`}]},{type:`steps`,items:[{title:`Công phu viên dung: Chánh Hạnh & Trợ Hạnh song hành`,text:`Bạn hoàn toàn có thể kết hợp cả hai: Lấy Niệm Phật “Nam Mô A Di Đà Phật” làm Chánh Hạnh xuyên suốt cả ngày, đồng thời trì tụng Chú Đại Bi hoặc tụng Kinh Địa Tạng làm Trợ Hạnh vào buổi sáng/tối để tiêu trừ nghiệp chướng, hộ vệ thân tâm an ổn. Đây là con đường tu tập vững vàng, tiến thoái đều có chỗ nương tựa.`},{title:`Giữ gìn Ngũ Giới & Làm tròn bổn phận đạo làm người`,text:`Tu tập chân thật không tách rời đời sống. Hãy luôn giữ trọn 5 giới căn bản (không sát sinh, không trộm cắp, không tà dâm, không nói dối, không say sưa rượu bia/chất độc hại) và chu toàn bổn phận làm con hiếu thảo, người vợ/chồng gương mẫu, công dân lương thiện. Sự an hòa của bản thân và gia đình chính là minh chứng rõ ràng nhất cho hoa trái tu tập.`}]},{type:`bullets`,title:`Lời khuyên cốt tủy trên đường tu học:`,items:[`Bền bỉ quan trọng hơn số lượng: Tu 20 phút thành tâm mỗi ngày quý giá hơn nhiều việc tu dồn một buổi vài tiếng rồi bỏ bê cả tuần.`,`Tâm thành kính là cội nguồn phước đức: Tụng niệm với tâm cung kính, sửa đổi lỗi lầm của bản thân, không chạy theo danh vọng hay cầu mong cảm ứng thần bí.`,`Gặp thuận duyên không khởi tâm kiêu mạn, gặp nghịch duyên không thối chuyển đạo tâm — biến mọi thử thách thành bậc thang tiến tu.`]},{type:`link`,href:`/tu-tap?article=kinh-dia-tang&mode=practice`,label:`Tu Tập: Vào thẳng khóa tụng Kinh Địa Tạng Bồ Tát Bổn Nguyện`,text:`Mở trực tiếp chế độ tụng Kinh Địa Tạng (13 phẩm, phân chia Thượng - Trung - Hạ) kèm chuông mõ và đánh dấu tiến trình.`,buttonLabel:`Vào tu tập Kinh Địa Tạng`},{type:`link`,href:`/tu-tap?mode=rosary`,label:`Tu Tập: Mở Tràng Hạt Niệm Phật (Nam Mô A Di Đà Phật)`,text:`Mở giao diện chuỗi hạt niệm Phật điện tử để hành trì danh hiệu Phật A Di Đà mọi lúc mọi nơi.`,buttonLabel:`Vào lần chuỗi Niệm Phật`},{type:`link`,href:`/?sach=niem-phat&q=Niệm+Phật`,label:`Sách: Pháp Môn Niệm Phật & Vãng Sanh Tịnh Độ`,text:`Tìm đọc các kinh sách hướng dẫn chi tiết công phu Niệm Phật, phát nguyện vãng sanh Tây Phương Cực Lạc.`,buttonLabel:`Đọc sách`}]}],faqs:[{id:`faq-nguoi-moi-nen-bat-dau-ngay-dau-the-nao`,question:`Tôi là người hoàn toàn mới, chưa biết gì thì ngày đầu tiên nên bắt đầu như thế nào?`,keywords:[`người mới`,`ngày đầu tiên`,`chưa biết gì`,`bắt đầu ra sao`,`làm gì`],answer:[`Ngày đầu tiên, bạn hãy giữ tinh thần thật nhẹ nhàng, thư thái, không cần tạo áp lực phải tụng ngay bài kinh dài. Hãy bắt đầu bằng việc đọc thử vài mẩu chuyện nhân quả người thật việc thật trong cuốn “Báo Ứng Hiện Đời” trên website để phát khởi niềm tin.`,`Sau đó, bạn mở mục “Tu Tập”, chọn bài “Chú Đại Bi”, bật âm thanh chuông mõ để nghe và đọc nhẩm theo 3 hoặc 7 biến, hoặc lần chuỗi hạt niệm 108 câu “Nam Mô A Di Đà Phật”. Thực hành nhẹ nhàng, an vui mỗi ngày sẽ giúp bạn tự nhiên bước vào đường tu một cách tự nhiên và bền bỉ.`],editorialStatus:`verified`},{id:`faq-chua-an-chay-truong-co-tu-duoc-khong`,question:`Chưa ăn chay trường được thì có được trì Chú Đại Bi và tụng Kinh Địa Tạng không?`,keywords:[`ăn chay`,`ăn mặn`,`ăn chay trường`,`trì chú`,`tụng kinh`,`phạm tội`],answer:[`Hoàn toàn được và rất nên tu tập. Đạo Phật luôn rộng mở đón nhận từng bước chuyển hóa xuất phát từ tâm của mỗi người.`,`Nếu chưa thể ăn chay trường ngay, bạn có thể bắt đầu bằng việc ăn chay các ngày trai (mồng một, hôm rằm) và hạn chế tối đa việc trực tiếp sát sinh. Vào những ngày ăn mặn, trước khi bước vào thời khóa tụng kinh hay trì chú, bạn chỉ cần tắm rửa sạch sẽ, đánh răng súc miệng kỹ càng, tránh ăn các loại gia vị nồng hôi (hành, tỏi, hẹ - ngũ vị tân) là có thể an tâm hành trì với tâm thành kính.`],editorialStatus:`verified`}]},{id:`huong-dan-tung-kinh`,icon:`📖`,title:`Hướng dẫn tụng kinh`,shortTitle:`Tụng Kinh`,keywords:[`tụng kinh`,`đọc kinh`,`ngày trai`,`sáng sớm`,`buổi tối`,`mang thai`,`nằm mộng`,`ngủ mơ`,`người bệnh nặng`,`49 ngày`,`khó khăn`,`địa tạng`,`lưu ý tụng kinh`],editorialStatus:`verified`,introduction:[`Tụng kinh là đọc lời Phật dạy với tâm thành kính, giúp hiểu đạo lý, tăng trưởng trí tuệ và gieo thiện duyên với Phật pháp. Công đức đọc tụng, chép kinh và ấn tống tôn kinh là không thể nghĩ bàn.`],topics:[{id:`thoi-gian-tung-kinh`,title:`Thời gian tụng kinh`,keywords:[`thời gian tụng`,`ngày trai`,`mồng một`,`hôm rằm`,`buổi sáng`,`buổi tối`,`ăn chay`,`giữ giới`],blocks:[{type:`cards`,items:[{title:`Tụng hằng ngày là tốt nhất`,text:`Nếu không có điều kiện, có thể tụng 1 tuần 1 lần hoặc 1 tháng 1 lần. Tốt nhất là vào các ngày trai: mồng 1, 8, 14, 15, 18, 23, 24, 28, 29, 30 âm lịch — kết hợp ăn chay, giữ giới thì công đức được nhân lên rất nhiều.`},{title:`Buổi sáng sớm hoặc tối trước khi ngủ`,text:`Hai thời điểm này tâm thường thanh tịnh nhất. Buổi sáng tụng để phát nguyện và khởi đầu ngày tốt lành. Buổi tối tụng để sám hối, hồi hướng và an định tâm trước khi nghỉ ngơi.`}]}]},{id:`hoan-canh-nen-tung-kinh-dia-tang`,title:`Các hoàn cảnh nên tụng Kinh Địa Tạng`,keywords:[`kinh địa tạng`,`mang thai`,`chuẩn bị mang thai`,`sinh con`,`nằm mộng`,`ngủ mơ`,`người mất`,`quỷ thần`,`người bệnh nặng`,`49 ngày`,`khó khăn`,`nguyện cầu`],blocks:[{type:`steps`,items:[{title:`Chuẩn bị mang thai / đang mang thai`,text:`Trước khi sinh ít nhất 7 ngày nên tụng kinh Địa Tạng (ít nhất 7 biến) và niệm danh hiệu Bồ Tát Địa Tạng đủ 10.000 lần — giúp đứa trẻ giải trừ quả báo đời trước, được an vui, dễ nuôi và thọ mạng tăng trưởng.`},{title:`Nằm mộng thấy người mất / quỷ thần`,text:`Đây thường là cha mẹ, anh chị em, quyến thuộc nhiều đời đang ở đường ác, nhờ người thân làm phước lành giúp họ. Nên phát nguyện tụng 3 hoặc 7 biến Kinh Địa Tạng hồi hướng cho họ.`},{title:`Nhà có người bệnh nặng`,text:`Người bệnh tự đọc hoặc người thân đọc thay. Nên tụng kinh hoặc dùng tiền cúng dường tạc tượng, thắp đèn dầu — giúp người bệnh vĩnh viễn thoát khỏi tai ương và trọng tội đời trước.`},{title:`Gia đình có người mới mất (trong 49 ngày)`,text:`Trong vòng 49 ngày, các cõi chưa định được nghiệp tội cho người mất. Họ trông mong thân quyến làm phước lành giúp giảm bớt nghiệp. Nên phát nguyện tụng 3 hoặc 7 biến hồi hướng cho người mất.`},{title:`Khi cuộc sống gặp nhiều khó khăn`,text:`Khi bị áp lực, có nguyện cầu muốn thành tựu, nên phát tâm tụng kinh liên tục 7 ngày, 21 ngày hoặc 49 ngày và niệm danh hiệu Địa Tạng Bồ Tát mỗi ngày ít nhất 1.000 lần không gián đoạn — thiện nguyện gì cũng đều được như ý.`}]}]},{id:`luu-y-khi-tung-kinh`,title:`Lưu ý khi tụng kinh`,keywords:[`lưu ý`,`đọc chậm`,`không có bàn thờ`,`tụng thầm`,`tâm tưởng`,`đánh răng`,`súc miệng`,`hồi hướng`],blocks:[{type:`bullets`,title:`Những điểm cần nhớ khi thực hành:`,items:[`Đọc chậm, rõ ràng, thành kính — không cần đọc nhanh hay đọc nhiều, cần đọc thấu.`,`Không nhất thiết phải có bàn thờ — tìm chỗ yên tĩnh, sạch sẽ để tụng.`,`Không tiện tụng ra tiếng thì tụng bằng tâm tưởng (khi ở chỗ đông người).`,`Trước khi tụng nên đánh răng, súc miệng, mặc quần áo sạch, kín đáo.`,`Sau khi tụng nên hồi hướng công đức cho tất cả chúng sinh.`]}]}]},{id:`huong-dan-tri-chu`,icon:`📿`,title:`Hướng dẫn trì chú`,shortTitle:`Trì Chú`,keywords:[`thần chú`,`dhāraṇī`,`trì chú`,`niệm chú`,`niệm phật`,`chánh hạnh`,`trợ hạnh`,`chú đại bi`,`chuẩn bị`,`ngũ vị tân`,`điều cần tránh`],editorialStatus:`verified`,introduction:[`Thần Chú (Dhāraṇī) là lời bí mật của chư Phật và Bồ Tát, có công năng bảo hộ thân tâm, tiêu trừ nghiệp chướng, phát sinh trí tuệ và tăng trưởng phước đức. Công đức trì chú chỉ người chuyên trì mới tự cảm nhận được.`],topics:[{id:`phan-biet-tri-va-niem-chu`,title:`Phân biệt Trì Chú và Niệm Chú`,keywords:[`phân biệt`,`trì chú`,`niệm chú`,`thuộc lòng`,`chưa thuộc`],blocks:[{type:`cards`,items:[{title:`Trì Chú`,text:`Thuộc làu chú đọc lặp đi lặp lại liên tục rất nhanh và nhiều lần cho đến khi nhuần nhuyễn. Đây là hình thức tu tập chính.`},{title:`Niệm Chú`,text:`Đọc chú (chưa thuộc) — chưa được gọi là trì, nhưng nếu thành tâm chuyên chú thì công đức vẫn không thể nghĩ bàn.`}]}]},{id:`tri-chu-va-niem-phat-ket-hop`,title:`Trì chú và niệm Phật — kết hợp đúng pháp`,keywords:[`chánh hạnh`,`trợ hạnh`,`vãng sanh`,`cực lạc`,`a di đà phật`,`chú đại bi`,`đi đường`,`oan gia trái chủ`],blocks:[{type:`steps`,items:[{title:`Niệm Phật là chánh hạnh`,text:`Nếu mục tiêu là cầu vãng sanh Tây Phương Cực Lạc, hãy dùng niệm Phật (Nam mô A Di Đà Phật) làm chánh hạnh. Lúc lâm chung chỉ cần niệm được 10 niệm danh hiệu Phật A Di Đà với tâm thành, Phật sẽ đến rước — đây là đại nguyện thứ 18 của Ngài.`},{title:`Trì chú là trợ hạnh`,text:`Trì chú giúp bảo hộ thân tâm, tiêu trừ nghiệp chướng, khiến cuộc sống hiện tại an ổn, giảm oan gia trái chủ phá hoại việc tu tập. Thời gian trì chú nên bằng hoặc ít hơn nửa thời gian niệm Phật.`},{title:`Chú Đại Bi — nên học thuộc`,text:`Mọi người nên cố gắng học thuộc Chú Đại Bi. Khi đi đường có thể tụng thầm — gieo duyên Phật đạo cho các chúng sinh hữu hình, vô hình nghe được thì công đức không thể nghĩ bàn.`}]}]},{id:`chuan-bi-truoc-khi-tri-chu-va-tung-kinh`,title:`Chuẩn bị trước khi trì chú và tụng kinh`,keywords:[`chuẩn bị`,`nên làm`,`cần tránh`,`ngũ vị tân`,`hành`,`tỏi`,`ngũ giới`,`tà dâm`,`uống rượu`,`quan hệ vợ chồng`,`bản hán việt`,`phạn ngữ`],blocks:[{type:`bullets`,title:`Những điều nên làm`,items:[`Đánh răng, súc miệng sạch sẽ trước khi tụng.`,`Mặc quần áo sạch, kín đáo, trang nghiêm.`,`Tìm chỗ yên tĩnh, sạch sẽ — hoặc đối trước bàn thờ Phật nếu có.`,`Giữ tâm thành kính, cung kính trong suốt thời gian trì chú, tụng kinh.`,`Kiêng cử ngũ vị tân (hành, hẹ, tỏi, kiệu, nén) trước khi tụng.`,`Giữ ít nhất là ngũ giới, đặc biệt giữ thân không uống rượu/bia và không tà dâm.`]},{type:`callout`,tone:`warning`,title:`Những điều cần tránh`,text:`Không tụng khi quan hệ vợ chồng (kể cả bằng tâm) — hãy ngưng hẳn việc tụng chú lúc này. Không nghi ngờ hay phân biệt bản tiếng Hán-Việt hay tiếng Phạn hơn kém — cả hai đều là một thể. Không tin vào tà thuyết như "chỉ được tụng ở chùa" hay "chỉ thầy mới tụng được" — đây là sai lầm.`},{type:`callout`,tone:`note`,title:`Có thể tụng bất cứ lúc nào`,text:`Giờ nào, ngày nào, lúc nào cũng có thể tụng chú được. Khi đi đường, làm việc nhà, đi bộ — có thể tụng thầm trong tâm. Khi ở chỗ không sạch sẽ hoặc đông người — tụng bằng tâm tưởng, không tụng ra tiếng.`}]}]},{id:`tho-tuong-tai-gia`,icon:`🪔`,title:`Khai quang tượng & thờ cúng Địa Tạng Bồ Tát tại gia`,shortTitle:`Thờ Tượng`,keywords:[`khai quang`,`thờ tượng`,`địa tạng bồ tát`,`tắm tượng`,`shipper`,`nước tắm phật`,`an vị`,`chú đại bi`,`bài thỉnh`,`tụng 7 ngày`],editorialStatus:`verified`,introduction:[`Các bạn nên tự làm tại nhà, không nên nhờ hay mướn sư thầy đến khai quang. Việc tự mình thực hiện với tâm thành kính thì công đức, phước báo sẽ viên mãn hơn, lại áp dụng được cho tất cả mọi người. Tượng có thể thỉnh ở bất cứ đâu tùy duyên.`],topics:[{id:`buoc-1-tam-tuong-khi-nhan-ve`,title:`Bước 1 — Tắm tượng khi nhận về`,keywords:[`tắm tượng`,`chuẩn bị đồ dùng`,`nước tắm phật`,`shipper`,`cất đồ`],blocks:[{type:`steps`,items:[{title:`Chuẩn bị đồ dùng`,text:`Chuẩn bị: 1 chai nước tắm Phật (mua ngoài tiệm), 1 cốc để múc nước, 1 chậu sạch, 1 khăn sạch.`},{title:`Nhận tượng từ shipper`,text:`Khi nhận tượng từ shipper, đỡ tượng bằng hai tay với tâm tôn kính. Pha nước ấm vào chậu, đổ nước tắm Phật vào, dùng cốc múc nước tắm tượng, rồi dùng khăn lau khô.`},{title:`Cất đồ tắm Phật`,text:`Sau khi tắm xong, cất các đồ dùng (cốc, chậu, khăn) vào một chỗ sạch sẽ, không dùng vào việc khác. Sau này có thể dùng lại để tắm tượng định kỳ.`}]}]},{id:`buoc-2-an-vi-tuong-va-doc-bai-thinh`,title:`Bước 2 — An vị tượng và đọc bài thỉnh`,keywords:[`an vị`,`bàn thờ`,`gia tiên`,`thổ địa`,`chú đại bi`,`bài thỉnh`,`kinh địa tạng 7 ngày`,`giáng lâm`],blocks:[{type:`steps`,items:[{title:`An vị tượng lên bàn thờ`,text:`Đặt tượng lên bàn thờ, thắp hương. Nếu bàn thờ đã có sẵn gia tiên hoặc thổ địa, phải kê tượng Bồ Tát cao hơn các vị thần và cao hơn bài vị tổ tiên — làm như vậy mới đúng pháp.`},{title:`Tụng Chú Đại Bi`,text:`Tụng 7 đến 21 biến Thần Chú Đại Bi với tâm thành kính.`},{title:`Đọc bài thỉnh (3 lần)`,text:`Sau khi tụng chú, thành tâm đọc bài thỉnh 3 lần đối trước tôn tượng Bồ Tát.`}]},{type:`quote`,title:`Bài thỉnh Địa Tạng Bồ Tát giáng lâm (đọc 3 lần):`,lines:[`"Con tên là… pháp danh… nay con đủ nhân duyên, phước báu được thiện tri thức giới thiệu, gieo duyên thỉnh tượng ngài Đại Bồ Tát Địa Tạng (nếu thỉnh tượng vị khác thì đọc tên vị đó) về thờ phụng."`,`"Kính mong Bồ Tát từ bi phân một thân giáng lâm tại chỗ con thờ tự, cúi xin Ngài từ bi thương xót độ hóa cho con và gia đình con khai ngộ Phật pháp, tin sâu nhân quả, muốn làm việc ác thì không thành, mà làm việc thiện thì thành tựu nhanh chóng."`,`"Cúi xin Bồ Tát từ bi thương xót độ hóa cho ông bà cha mẹ tổ tiên nhiều đời nhiều kiếp, các oan gia trái chủ quá khứ hiện tại của con và gia đình con lìa khổ được vui, siêu thoát về cõi lành."`]},{type:`steps`,items:[{title:`Tụng Kinh Địa Tạng 7 ngày`,text:`Từ ngày thỉnh tượng về đến 7 ngày sau, chuyên trì tụng Kinh Địa Tạng mỗi ngày 1 biến. Làm như vậy là được — Ngài sẽ phân một thân nhập vào tượng ở nhà bạn.`}]}]},{id:`dieu-quan-trong-nhat-khi-tho-tuong`,title:`Điều quan trọng nhất`,keywords:[`tôn kính`,`kê tượng cao`,`tùy duyên`,`tài liệu thờ phụng`],blocks:[{type:`bullets`,items:[`Thực hiện tất cả các bước với tâm tôn kính nhất — đây là yếu tố quyết định phước báo.`,`Nếu bàn thờ đã có gia tiên hoặc thổ địa, tượng Bồ Tát phải đặt cao hơn tất cả.`,`Tượng có thể thỉnh ở bất cứ đâu tùy duyên, không nhất thiết phải thỉnh tại chùa.`]},{type:`link`,href:`https://docs.google.com/document/d/15GU4qjPNpA3k6P4fAA07xbCpmKT1bOq3n2wz1ie8Gfc/edit?tab=t.0`,label:`Tài liệu hướng dẫn thờ phụng và cúng dường Địa Tạng Bồ Tát`,text:`Tải tài liệu đầy đủ hướng dẫn cách thờ phụng, cúng dường và pháp môn tu tập với Địa Tạng Bồ Tát`}]}]},{id:`thuc-hanh-hang-ngay`,icon:`📋`,title:`Thực hành hằng ngày`,shortTitle:`Thực Hành`,keywords:[`thực hành hằng ngày`,`buổi sáng`,`khởi tâm lành`,`phát nguyện`,`ban ngày`,`hành thiện`,`niệm thầm`,`buổi tối`,`sám hối`,`hồi hướng`,`nguyên tắc cốt lõi`,`ngũ giới`],editorialStatus:`verified`,introduction:[`Một nếp sống tu tập tỉnh thức, đều đặn mỗi ngày giúp chuyển hóa nghiệp lực, mang lại bình an cho bản thân và gia đình.`],topics:[{id:`khung-thoi-khoa-trong-ngay`,title:`Thời khóa thực hành trong ngày`,keywords:[`buổi sáng`,`ban ngày`,`buổi tối`,`phát nguyện`,`hành thiện`,`sám hối`,`hồi hướng`],blocks:[{type:`steps`,items:[{title:`Buổi sáng — Khởi tâm lành`,text:`Thức dậy, dành 5 phút phát niệm danh hiệu Nam mô A Di Đà Phật, Nam mô Đại Bi Quán Thế Âm Bồ Tát, Nam mô Địa Tạng Bồ Tát rồi phát nguyện 3 lần: "Hôm nay con nguyện luôn làm điều lành, không làm điều ác, cố gắng giúp đỡ chúng sinh và giữ tâm thanh tịnh." Rồi tụng thời khóa sáng: niệm Phật, trì chú, tụng kinh.`},{title:`Ban ngày — Hành thiện & niệm thầm`,text:`Giúp đỡ người khác dù chỉ một việc nhỏ. Tranh thủ mọi thời gian rảnh để niệm thầm danh hiệu Phật hoặc trì chú trong lòng — đi đường, nấu cơm, chờ đợi đều được.`},{title:`Buổi tối — Sám hối & hồi hướng`,text:`Trước khi ngủ, nhìn lại ngày đã qua: nếu làm điều sai trái hãy thành tâm sám hối và nguyện không tái phạm. Sau đó hồi hướng toàn bộ công đức tu tập trong ngày cho tất cả chúng sinh.`}]}]},{id:`nguyen-tac-cot-loi`,title:`Nguyên tắc cốt lõi`,keywords:[`nguyên tắc`,`đều đặn`,`tâm thành kính`,`ngũ giới`,`kiên trì`,`nhẫn nhục`],blocks:[{type:`bullets`,items:[`Đều đặn quan trọng hơn nhiều — tu 15 phút mỗi ngày tốt hơn tu 3 giờ 1 tuần một lần.`,`Tâm thành kính quan trọng hơn hình thức — niệm Phật 5 phút thành tâm hơn 1 giờ qua loa.`,`Nền tảng tu tập: tránh sát sinh, nói dối, tà dâm, trộm cắp, uống rượu.`,`Kiên trì và nhẫn nhục — tu tập là hành trình dài, không cầu thành quả ngay.`]}]}]},{id:`bo-thi-may-nghe-phap`,icon:`📻`,title:`Hướng dẫn bố thí pháp — Đặt máy nghe pháp & niệm Phật độ vong linh`,shortTitle:`Bố Thí Pháp`,keywords:[`bố thí pháp`,`máy nghe pháp`,`máy niệm phật`,`thẻ nhớ`,`FAT32`,`độ vong linh`],editorialStatus:`verified`,introduction:[`Trong Kinh Pháp Cú (câu 354), Đức Phật từng dạy: “Pháp thí thắng mọi thí, Pháp vị thắng mọi vị, Pháp hỷ thắng mọi hỷ, Ái diệt dứt mọi khổ”. Bố thí tiền tài (Tài thí) chỉ giúp chúng sinh vơi bớt đói khổ trong nhất thời, nhưng Bố thí Pháp (Pháp thí) lại gieo chủng tử giác ngộ ngàn đời, giải cứu chúng sinh thoát khỏi đọa đày luân hồi sinh tử.`],topics:[{id:`y-nghia-va-cong-duc-phap-thi-may-nghe-phap`,title:`1. Ý nghĩa & Công đức thù thắng của việc đặt máy niệm Phật cõi âm`,keywords:[`pháp thí`,`niệm Phật`,`công đức`],blocks:[{type:`paragraph`,text:`Bố thí máy nghe pháp và máy niệm Phật tại những nơi âm u, lạnh lẽo, nhiều vong linh u uất (như nghĩa trang, khúc đường hay xảy ra tai nạn, gần bệnh viện, nhà xác...) là một pháp tu thiện xảo thù thắng: chi phí tài chính bỏ ra rất khiêm tốn (chỉ vài chục ngàn đến hơn một trăm ngàn đồng mỗi máy), nhưng tạo dựng nên một “đạo tràng thuyết pháp lưu động” hoạt động bền bỉ ngày đêm 24/24, mang lại công đức vô lượng vô biên cho cả người cúng dường lẫn muôn loài hương linh thọ nhận.`},{type:`paragraph`,text:`Việc đặt máy nghe pháp nơi cõi âm hoàn toàn xuất phát từ LÒNG TỪ BI THƯƠNG XÓT muôn loài, không vụ lợi, không sợ hãi, cũng không phải để cầu xin tài lộc quỷ thần. Khi mang máy đến nơi đặt, hãy giữ thân tâm thanh tịnh, chắp tay trang nghiêm và đọc lời khấn nguyện chân thành:`}]},{id:`chuan-bi-may-va-the-nho-nghe-phap`,title:`2. Chuẩn bị máy nghe pháp & Lưu ý quan trọng khi chọn mua`,keywords:[`máy nghe pháp`,`thẻ nhớ`,`thẻ 4G`,`MicroSD`,`FAT32`],blocks:[{type:`callout`,tone:`note`,title:`LƯU Ý CỰC KỲ QUAN TRỌNG KHI MUA: Phải chọn máy CÓ KHE CẮM THẺ NHỚ`,text:`Hiện nay trên thị trường có nhiều dòng máy niệm Phật mini giá rẻ nhưng bị nạp chết sẵn vài câu niệm Phật vào vi mạch bên trong, không có khe cắm thẻ nhớ ngoài nên không thể copy thêm bài pháp hay kinh tụng theo ý muốn. Khi tìm mua trên các sàn thương mại điện tử (Shopee, Lazada, TikTok Shop) hoặc cửa hàng Phật giáo, bạn CẦN CHỌN LOẠI CÓ KHE CẮM THẺ NHỚ (MicroSD / TF card) hoặc cổng cắm USB để có thể chủ động chép kho bài pháp tuyển chọn.`},{type:`steps`,items:[{title:`1. Chọn loại máy nghe pháp / niệm Phật`,text:`Có hai dòng máy phổ biến: (1) Máy niệm Phật mini cầm tay (dùng pin sạc qua cổng Type-C / Micro USB hoặc cắm sạc dự phòng); (2) Máy niệm Phật năng lượng mặt trời chuyên dụng ngoài trời (tự động nạp pin khi có ánh nắng ban ngày, chống chịu thời tiết tốt, rất tiện để ở nghĩa trang xa xôi).`},{title:`2. Chuẩn bị thẻ nhớ MicroSD 4GB (thẻ 4G) định dạng FAT32`,text:`Bạn chuẩn bị một chiếc thẻ nhớ MicroSD dung lượng 4GB (thẻ 4G). Đặc biệt lưu ý: Thẻ nhớ cần được định dạng (format) về chuẩn FAT32 để máy nghe pháp / niệm Phật có thể nhận diện và phát được các tệp âm thanh. Dung lượng 4GB hoàn toàn vừa vặn và tối ưu để lưu trữ trọn bộ kho bài kinh và niệm Phật tuyển chọn.`},{title:`3. Cài đặt chế độ phát lặp lại (Loop)`,text:`Sau khi cắm thẻ nhớ vào máy, hãy bấm nút Mode hoặc nút Repeat để chọn chế độ phát: Lặp lại một bài (Single Loop — ví dụ chỉ lặp liên tục câu Phật hiệu A Di Đà Phật thanh tịnh) hoặc Lặp lại toàn bộ danh mục (All Loop) để máy tự động phát lần lượt suốt ngày đêm.`}]}]},{id:`vi-tri-dat-may-va-cach-che-chan-ngoai-troi`,title:`3. Vị trí đặt máy & Cách che chắn mưa nắng ngoài trời`,keywords:[`ngoài trời`,`mưa nắng`,`nghĩa trang`,`âm lượng`],blocks:[{type:`bullets`,title:`Những địa điểm rất cần tiếng kinh câu niệm Phật:`,items:[`Khu nghĩa trang, nghĩa địa, phần mộ tổ tiên gia đình hoặc những khu mồ mả vô chủ, hoang vắng không người hương khói.`,`Miếu cô hồn hoang phế, gốc cây cổ thụ nơi đất trống, hoặc đặt ngay tại một góc thanh tịnh trong sân vườn nhà bạn.`]},{type:`steps`,items:[{title:`Che chắn chống mưa nắng hiệu quả`,text:`Chọn hộp và vị trí che chắn phù hợp với thiết bị; giữ khô ráo, thông thoáng và kiểm tra định kỳ. Chỉ đặt khi được chủ quản nơi đó đồng ý, tránh làm phiền hoặc cản trở người xung quanh.`},{title:`Cố định vị trí cao ráo, kín đáo`,text:`Dùng dây rút nhựa hoặc dây kẽm buộc chắc chắn hộp máy vào cành cây cao, kẽ đá, hốc tường hoặc dưới mái hiên. Đặt ở vị trí cao vừa tránh ẩm mốc ngập nước, tránh súc vật quấy phá, lại kín đáo tế nhị để người qua đường không tò mò táy máy.`},{title:`Chỉnh âm lượng vừa phải, thanh thoát`,text:`Điều chỉnh âm lượng nhẹ nhàng, vừa đủ nghe, tôn trọng sự yên tĩnh của người xung quanh.`}]}]},{id:`tam-luong-va-nghi-thuc-khan-nguyen`,title:`4. Tâm lượng từ bi & Nghi thức khấn nguyện khi đặt máy`,keywords:[`tâm từ bi`,`khấn nguyện`,`hồi hướng`],blocks:[{type:`paragraph`,text:`Việc đặt máy nghe pháp nơi cõi âm hoàn toàn xuất phát từ LÒNG TỪ BI THƯƠNG XÓT muôn loài, không vụ lợi, không sợ hãi, cũng không phải để cầu xin tài lộc quỷ thần. Khi mang máy đến nơi đặt, hãy giữ thân tâm thanh tịnh, chắp tay trang nghiêm và đọc lời khấn nguyện chân thành:`},{type:`bullets`,title:`Hồi hướng công đức thường nhật:`,items:[`Hằng ngày sau khi hoàn thành thời khóa tụng kinh, niệm Phật hoặc làm việc thiện lành tại gia, hãy nhớ phát tâm hồi hướng công đức cho các hương linh nơi bạn đã đặt máy.`,`Định kỳ ghé qua kiểm tra pin, vệ sinh hộp máy và sạc lại điện nếu dùng máy pin sạc thường.`]}]},{id:`tai-ve-cac-bai-phap-tuyen-chon-cho-the-nho`,title:`5. Tải về kho bài Pháp & Niệm Phật tuyển chọn để chép vào thẻ nhớ`,keywords:[`tải về`,`thẻ nhớ`,`Google Drive`,`giải nén`,`Kinh Địa Tạng`,`Tôn Thắng`],blocks:[{type:`bullets`,title:`Danh mục các bài tuyển chọn có trong tệp tải về:`,items:[`1. Kinh Địa Tạng Bồ Tát Bổn Nguyện (Diễn đọc trọn bộ) — bộ kinh căn bản độ âm thù thắng.`,`2. Thần Chú Tôn Thắng Phật Đảnh Đà La Ni (21 biến) — oai lực đệ nhất tiêu trừ ác nghiệp, cứu bạt địa ngục.`,`3. Bài khai thị cho Hương Linh, Vong Linh (Cửu Huyền Thất Tổ).`,`4. Lời khai thị cho người sắp lâm chung.`,`5. Nam Mô Địa Tạng Vương Bồ Tát (Thầy Thích Trí Thoát tụng).`,`6. Kinh Phổ Môn Diễn Đọc (Quán Thế Âm Bồ Tát cứu khổ cứu nạn).`,`7. Nam Mô Quan Thế Âm Bồ Tát.`,`8. Kinh A Di Đà diễn đọc.`,`9. Nam Mô A Di Đà Phật (bản mới trang nghiêm thanh tịnh).`,`10. Kinh Đại Thừa Vô Lượng Thọ (HT. Thích Đức Niệm dịch).`,`11. Tán Thán Phật A Di Đà Và Cõi Cực Lạc.`,`12. Kinh Quán Vô Lượng Thọ Phật.`,`13. Quê Hương Cực Lạc (Hòa thượng Tuyên Hóa khai thị).`,`14. Kinh Nghiệp Báo Sai Biệt.`,`15. Kinh Nhân Quả Ba Đời.`,`16. Diễn đọc Kinh Thập Thiện Nghiệp Đạo.`,`17. Kinh Dược Sư Lưu Ly Quang Như Lai Bổn Nguyện Công Đức.`,`18. Nam Mô Dược Sư Lưu Ly Quang Vương Phật (Thầy Thích Trí Thoát tụng).`,`19. Kinh Hoa Nghiêm — Phẩm Phổ Hiền Hạnh Nguyện.`,`20. Phẩm 5: Diệt Trừ Nghiệp Chướng (Kinh Ánh Sáng Hoàng Kim).`,`21. Kinh Đại Bi Tâm Đà La Ni.`,`22. Chú Đại Bi tiếng Phạn 21 biến (Quang Từ).`,`23. Kinh Đại Thừa Trang Nghiêm Bảo Vương.`,`24. Om Mani Padme Hum (Lục Tự Đại Minh Chú).`,`25. Kinh Phật Đảnh Tôn Thắng Đà Ra Ni.`,`26. Kinh Đại Thừa Công Đức Tạo Tượng Phật và Phát Bồ Đề Tâm Văn.`,`27. Kinh Phước Báo Của Tạo Lập Hình Tượng Phật.`,`28. Kinh Quán Thế Âm Bồ Tát Thọ Ký.`,`29. Diễn đọc Phật Thuyết Kinh Từ Thị Bồ Tát Đại Thành Phật.`]},{type:`paragraph`,text:`1. Nhấp vào liên kết Google Drive bên dưới để tải tệp nén về máy tính hoặc điện thoại.
2. Sau khi tải về xong, bạn tiến hành GIẢI NÉN tệp để nhận toàn bộ thư mục các file MP3.
3. Chuẩn bị thẻ nhớ MicroSD dung lượng 4GB (thẻ 4G), đảm bảo thẻ nhớ đã được định dạng (format) ở chuẩn FAT32.
4. Sao chép (copy) toàn bộ các file MP3 vừa giải nén vào thư mục gốc của thẻ nhớ 4G.
5. Cắm thẻ nhớ vào khe cắm của máy nghe pháp/niệm Phật là máy sẽ tự động nhận và phát tuần tự mượt mà suốt ngày đêm.`},{type:`paragraph`,text:`Nếu không rành thao tác công nghệ hoặc không có sẵn máy tính và đầu đọc thẻ nhớ, quý Phật tử chỉ cần mang thẻ nhớ (hoặc mua luôn thẻ 4G tại tiệm) ra các quán điện thoại, cửa hàng phụ kiện điện thoại hoặc quán sửa chữa máy tính gần nhà. Bạn chỉ việc gửi đường link Google Drive bên dưới cho nhân viên và nhờ họ tải về, giải nén rồi copy toàn bộ các file MP3 vào thẻ nhớ với định dạng FAT32. Các bạn kỹ thuật viên thao tác việc này rất quen thuộc và chỉ mất khoảng 2 - 3 phút là hoàn tất.`},{type:`link`,href:`https://drive.google.com/file/d/1QSNeYvzkTMsNorQ_23b3W1TIYrQekYeH/view?usp=sharing`,externalActions:!0,label:`Tải kho bài pháp tuyển chọn`,text:`Liên kết Google Drive chính thức từ tác giả — tải tệp nén về máy tính/điện thoại, giải nén và chép vào thẻ nhớ 4G định dạng FAT32 (hoặc gửi link nhờ quán điện thoại/máy tính tải giúp).`,buttonLabel:`Mở Google Drive`}]}]},{id:`gioi-thieu-tac-gia`,icon:`👤`,title:`Giới thiệu về tác giả`,shortTitle:`Tác Giả`,keywords:[`quang từ`,`ngộ quang từ`,`tác giả`,`cư sĩ`,`ngọc lịch bửu phiêu`,`thạch mỹ nghi`,`địa tạng bồ tát`,`quán thế âm bồ tát`,`messenger`,`facebook`],editorialStatus:`verified`,introduction:[],topics:[{id:`tieu-su-quang-tu`,title:`Cư sĩ Ngộ Quang Từ & Tâm nguyện phụng sự`,keywords:[`quang từ`,`ngộ quang từ`,`tiểu sử`,`cơ duyên`,`đạo tràng trực tuyến`],blocks:[{type:`paragraph`,text:`Tôi là cư sĩ Ngộ Quang Từ (thường gọi là Quang Từ), là một người con Phật tại gia có nhân duyên sâu dày với Chánh pháp. Trên bước đường đời, tôi đã từng đi qua không ít những thăng trầm, biến cố dập dồn, nghịch cảnh và những thử thách tưởng chừng khó bề vượt khỏi. Chính trong những thời khắc tăm tối và bế tắc ấy, nhờ có duyên lành được diện kiến Chánh pháp nhiệm màu, tôi dần thấu suốt những chân lý sâu xa mà Đức Phật đã truyền trao, đặc biệt là niềm tin sâu sắc không thể lay chuyển vào quy luật nhân quả nghiệp báo. Theo sự chiêm nghiệm tự thân qua bao năm tháng tu học, tôi nhận ra đây chẳng phải là sự tình cờ trong một kiếp này, mà là sự tiếp nối của những thiện căn, thiện duyên đã được gieo trồng và huân tập qua vô lượng kiếp quá khứ.`},{type:`paragraph`,text:`Trên con đường học Phật và hành trì, tôi luôn khắc cốt ghi tâm ân đức từ bi vô lượng của Đức Đại Nguyện Địa Tạng Vương Bồ Tát và Đức Đại Bi Quán Thế Âm Bồ Tát. Các Ngài đã dang tay che chở, soi sáng và dìu dắt tôi từng bước đi qua những đoạn đường gian khó, giúp tôi chuyển hóa nội tâm, hóa giải oan trái và đứng dậy từ những vấp ngã. Khởi sinh từ lòng chí thành tri ân Tam Bảo và chư Đại Bồ Tát, tôi đã phát khởi tâm nguyện sâu sắc: nguyện đem chút thân tâm hèn mọn này góp phần hoằng dương Chánh pháp, lan tỏa ánh sáng giác ngộ cùng những lời dạy quý báu của chư Phật, chư Tổ đến muôn nơi, gieo duyên lành cho những ai đang tìm kiếm con đường giải thoát khỏi khổ đau.`},{type:`paragraph`,text:`Trước đây, tôi từng có duyên lành tham gia công tác hoằng pháp tại trang Ngọc Lịch Bửu Phiêu của cô Thạch Mỹ Nghi, miệt mài chia sẻ các bài học về nhân quả, thiện ác báo ứng, đạo hiếu làm con và phương pháp thực tế để chuyển hóa khổ đau trong đời sống gia đình, xã hội. Trong suốt quá trình chuyên tâm tu học và thực chứng tâm linh, tôi đã trải qua những chiêm nghiệm mầu nhiệm sâu sắc, càng củng cố niềm tin tuyệt đối vào quy luật nghiệp báo luân hồi và sự hiện hữu chân thật của các cảnh giới vô hình trong pháp giới.`},{type:`paragraph`,text:`Thấu hiểu rằng trong thời đại công nghệ số đầy bộn bề và cám dỗ, con người rất dễ bị cuốn vào vòng xoáy lo toan, danh lợi, để rồi tâm trí bất an, cô đơn và lạc lõng; tôi đã ấp ủ và dốc trọn tâm lực xây dựng nên ứng dụng Tu Tập Phật Pháp này. Ứng dụng được thiết kế như một đạo tràng trực tuyến trang nghiêm và thanh tịnh, nơi bất kỳ ai, dù bận rộn hay ở nơi xa xôi không có điều kiện đến chùa, đều có thể mở điện thoại lên để công phu, lễ Phật, niệm Phật, tọa thiền, chép kinh và lắng nghe pháp âm. Ứng dụng được phát hành hoàn toàn miễn phí với tâm nguyện phụng sự vô vị lợi, không ngoài mục đích giúp đại chúng tin sâu nhân quả, đoạn trừ điều ác, siêng làm việc lành, chuyển hóa nghiệp lực và tìm lại sự an lạc nội tại.`},{type:`paragraph`,text:`Để ứng dụng Tu Tập Phật Pháp có thể ra đời, hoàn thiện và phụng sự quý Phật tử như ngày hôm nay, tôi xin gửi lời tri ân sâu sắc và chân thành nhất đến vợ tôi là chị Ôn Nhật Nga đã luôn kề vai sát cánh, thấu hiểu, hy sinh và đồng hành hỗ trợ hết mình trong suốt quá trình tôi xây dựng ứng dụng; anh Nguyễn Anh Tuấn (Giám đốc Công ty Cổ phần SMOB - SMOB Joint Stock Company) đã tận tình hỗ trợ về mặt kỹ thuật chuyên sâu và tài trợ hạ tầng tải ứng dụng, giúp ứng dụng vận hành mượt mà, ổn định trên các thiết bị Apple (iOS/macOS/iPadOS); em Quang Chiến đã tận tâm hỗ trợ xây dựng và vận hành hệ thống backend server, bảo đảm hạ tầng máy chủ luôn thông suốt, an toàn; em Đỗ Chân Đức đã hoan hỷ phát tâm cung cấp bản quyền hai tác phẩm quý báu: 'Sứ Mệnh Độ Vong' và 'Sứ Mệnh Thầy Pháp' để bổ sung vào kho tàng kinh sách của ứng dụng; cùng toàn thể cộng đồng Phật tử và các đạo hữu gần xa đã nhiệt thành giúp test lỗi, đóng góp những ý kiến vô cùng quý báu trong quá trình phát triển. Tôi xin nguyện đem toàn bộ công đức xây dựng ứng dụng này hồi hướng cho khắp pháp giới chúng sinh đều sớm thâm nhập Phật pháp, tiêu trừ nghiệp chướng, phước huệ trang nghiêm. Kính chúc toàn thể quý vị cùng gia quyến luôn thân tâm an lạc, vạn sự cát tường, bồ đề tâm kiên cố và tinh tấn viên mãn trên con đường tu học giải thoát!`},{type:`paragraph`,text:`Mọi thắc mắc liên quan đến ứng dụng hoặc các nội dung được chia sẻ trên ứng dụng, quý vị có thể liên hệ trực tiếp với tôi thông qua tài khoản Facebook hoặc nhắn tin qua Messenger được đính kèm bên dưới. Xin chân thành cảm ơn quý vị đã ghé thăm và đồng hành cùng ứng dụng Tu Tập Phật Pháp.`},{type:`link`,href:`https://m.me/tranan.buhd`,label:`Nhắn tin qua Messenger`,text:`Trò chuyện hoặc gửi câu hỏi trực tiếp đến Quang Từ qua Messenger (m.me/tranan.buhd)`},{type:`link`,href:`https://www.facebook.com/tranan.buhd/`,label:`Trang Facebook cá nhân`,text:`Truy cập trang cá nhân của Quang Từ (facebook.com/tranan.buhd)`}]}]},{id:`hoi-dap-thuong-gap`,icon:`❓`,title:`Hỏi đáp nhanh thường gặp`,shortTitle:`Hỏi Đáp`,keywords:[`faq`,`hỏi đáp`,`đi làm`,`phụ nữ tới ngày`,`kinh nguyệt`,`không có bàn thờ`,`xóa trình duyệt`,`máy tính`],editorialStatus:`verified`,introduction:[`Tổng hợp những băn khoăn thường gặp của quý đạo hữu trên bước đường tu học tại gia và thực hành ứng dụng, giúp gỡ bỏ những nghi ngại để an tâm tinh tấn mỗi ngày.`],topics:[],faqs:[{id:`faq-ban-di-lam-tu-luc-nao`,question:`Tôi bận đi làm cả ngày thì nên tu tập vào khung giờ nào?`,keywords:[`bận`,`đi làm`,`khung giờ`,`sáng`,`tối`,`thời gian`,`tại gia`],answer:[`Đạo Phật là đạo thực tế và từ bi, “Phật pháp tại thế gian, bất ly thế gian giác”. Đức Phật và chư Tổ chưa từng khuyên người cư sĩ tại gia phải buông bỏ bổn phận gia đình, việc làm mưu sinh để ép mình vào những khóa lễ dài quá sức. Trọng tâm của việc tu tập chính là chuyển hóa tâm thức, giữ tâm bình an và thiện lành ngay giữa những bận rộn đời thường.`,`Quý đạo hữu chỉ cần khéo léo chọn một khung giờ cố định mà bản thân cảm thấy thoải mái và tỉnh táo nhất: có thể là 15 – 30 phút vào buổi sáng sớm trước khi đi làm (để nạp năng lượng an lành), hoặc buổi tối sau khi hoàn tất công việc (để lắng dịu tâm trí trước giấc ngủ). Một thời khóa ngắn từ 10 đến 15 phút nhưng được duy trì đều đặn mỗi ngày như dòng nước chảy êm đềm sẽ mang lại công đức và sự an định sâu sắc hơn nhiều so với việc lập kế hoạch tu thật dài rồi sớm bỏ cuộc vì kiệt sức.`,`Bên cạnh đó, bạn hoàn toàn có thể tu trong từng công việc: khi rửa bát, đi bộ, chờ xe hay giải lao, chỉ cần khởi tâm niệm vài câu “Nam Mô A Di Đà Phật”, “Nam Mô Quán Thế Âm Bồ Tát” hay trì thầm một biến Chú Đại Bi. Giữ được chánh niệm trong từng hơi thở và công việc hằng ngày chính là pháp tu thù thắng nhất của người Phật tử tại gia.`],editorialStatus:`verified`},{id:`faq-phu-nu-toi-ngay`,question:`Phụ nữ tới ngày có được tụng kinh, thắp nhang bàn thờ không?`,keywords:[`kinh nguyệt`,`tới ngày`,`phụ nữ`,`thắp nhang`,`có tội`,`phạm giới`,`ô uế`,`bàn thờ`],answer:[`Hoàn toàn được và không hề có tội hay phạm giới. Quan niệm phụ nữ trong kỳ kinh nguyệt là “ô uế”, không được bước vào chánh điện hay không được thắp nhang, tụng kinh là một định kiến thế tục hủ lậu và mê tín dân gian, hoàn toàn trái ngược với giáo lý từ bi và bình đẳng của Đức Phật.`,`Kinh nguyệt là chu kỳ sinh lý tự nhiên và thanh tịnh của cơ thể người nữ để thực hiện thiên chức làm mẹ thiêng liêng. Chư Tổ sư (như Ấn Quang Đại Sư) đã nhiều lần từ ái khai thị: Trong những ngày này, người nữ chỉ cần chú ý vệ sinh thân thể sạch sẽ, súc miệng, rửa tay tươm tất, y phục trang nhã kín đáo là có thể an tâm bước lên bàn thờ thắp hương, lễ Phật, tụng kinh và trì chú như bình thường. Tâm thành kính hướng Phật mới là điều thanh tịnh tối thượng, chư Phật và Bồ Tát chỉ nhìn vào lòng chí thành chứ tuyệt đối không vì quy luật sinh lý tự nhiên của cơ thể mà quở phạt hay phân biệt đối xử.`,`Nếu trong những ngày này cơ thể cảm thấy mệt mỏi hoặc đau nhức, bạn không nhất thiết phải quỳ lạy nhiều khiến thân xác lao nhọc. Thay vào đó, bạn có thể ngồi ngay ngắn, hoặc thậm chí nằm nghỉ ngơi tĩnh dưỡng và mở ứng dụng Tu Tập Phật Pháp để nghe đọc tụng kinh điển, nghe Pháp thoại hay nhẩm niệm danh hiệu Phật trong tâm. Đạo Phật luôn lấy sự an lạc của thân tâm làm gốc, miễn là lòng bạn luôn tha thiết hướng về Tam Bảo.`],editorialStatus:`verified`},{id:`faq-khong-co-ban-tho`,question:`Không có bàn thờ Phật thì có được tụng kinh trên app không?`,keywords:[`không bàn thờ`,`tụng ở nhà`,`tụng trên app`,`điện thoại`,`phòng trọ`,`chân tâm`],answer:[`Hoàn toàn được. Đức Phật dạy: “Tất cả chúng sinh đều có Phật tánh”, và “Phật tại tâm khởi”. Bàn thờ hình tướng bên ngoài là một phương tiện tôn nghiêm giúp người tu tập dễ dàng sinh tâm cung kính, nhưng bàn thờ trang nghiêm nhất chính là một tấc lòng thành và tâm hướng thiện của chính bạn.`,`Đối với nhiều bạn sinh viên, người đi làm thuê ở phòng trọ chật hẹp, người đi công tác xa, hay sống cùng gia đình người thân chưa cùng tín ngưỡng, việc không có điều kiện lập bàn thờ Phật là hoàn cảnh rất phổ biến và hoàn toàn bình thường. Bạn đừng để hình thức bên ngoài trở thành rào cản ngăn bước đường tu học của mình.`,`Chỉ cần bạn chọn một góc ngồi sạch sẽ, yên tĩnh trong phòng, ngồi ngay ngắn với trang phục tươm tất, mở ứng dụng Tu Tập Phật Pháp trên điện thoại, chiêm ngưỡng tôn tượng Đức Phật trang nghiêm trên màn hình và thành kính quán tưởng dung nhan từ bi của Ngài đang hiện diện chứng minh. Bạn có thể sử dụng tai nghe để vừa giữ được sự tập trung sâu lắng cho tâm mình, vừa không gây ảnh hưởng đến không gian chung của người xung quanh. Nơi nào có tâm chí thành cung kính, nơi đó chính là đạo tràng thanh tịnh được chư Phật, Bồ Tát và chư vị thiện thần từ bi gia hộ.`],editorialStatus:`verified`},{id:`faq-xoa-trinh-duyet`,question:`Dữ liệu công phu của tôi có bị mất khi tôi xóa trình duyệt không?`,keywords:[`xóa cache`,`xóa dữ liệu`,`mất dữ liệu`,`google sync`,`đổi điện thoại`,`đồng bộ`,`tài khoản`,`sao lưu`],answer:[`Chúng tôi rất trân quý từng giọt công phu, từng chuỗi hạt và từng trang kinh mà quý đạo hữu đã dày công huân tập mỗi ngày. Khi bạn sử dụng ứng dụng ở chế độ khách (chưa đăng nhập), mọi dữ liệu nhật ký tu tập, số biến trì chú hay lịch sử đọc sách chỉ được lưu tạm trên bộ nhớ cục bộ của trình duyệt hoặc thiết bị. Do đó, nếu bạn vô tình thao tác xóa cache, xóa dữ liệu trình duyệt, gỡ bỏ ứng dụng hoặc đổi sang máy mới, những thông tin này sẽ có nguy cơ bị mất dữ liệu vĩnh viễn.`,`Để bảo vệ trọn vẹn tiến trình công phu quý báu, quý vị chỉ cần thực hiện đăng nhập bằng Google hoặc bằng Apple trên thiết bị iOS. Khi đã đăng nhập và thiết bị có kết nối mạng Internet, toàn bộ dữ liệu tu tập sẽ được tự động lưu trữ và đồng bộ hóa an toàn lên hệ thống đám mây (tương tự tính năng google sync tiện lợi). Nhờ đó, dù bạn có đổi điện thoại, xóa dữ liệu trình duyệt hay sử dụng song song nhiều thiết bị khác nhau, chỉ cần đăng nhập lại là toàn bộ công phu sẽ được khôi phục nguyên vẹn ngay lập tức.`,`Đối với các bản chép kinh bằng tay hoặc gõ phím, xin lưu ý luôn nhấn nút “Lưu lên hệ thống” sau mỗi thời khóa chép để bản ghi được bảo toàn chắc chắn. Riêng đối với các tệp sách PDF và file âm thanh Pháp thoại đã tải về để nghe ngoại tuyến, do có dung lượng lớn được lưu trực tiếp trong bộ nhớ máy, nếu bạn xóa ứng dụng hoặc chuyển sang thiết bị mới, bạn chỉ cần bấm tải lại một lần là có thể tiếp tục sử dụng như bình thường.`],editorialStatus:`verified`},{id:`faq-dung-tren-may-tinh`,question:`App có dùng được trên máy tính không?`,keywords:[`desktop`,`laptop`,`windows`,`mac`,`cài pwa`,`máy tính`,`trình duyệt`,`màn hình lớn`],answer:[`Hoàn toàn được. Ứng dụng Tu Tập Phật Pháp được tối ưu hoàn hảo để hoạt động mượt mà trên mọi loại máy tính để bàn (desktop) và laptop chạy hệ điều hành Windows, macOS hay Linux. Không gian màn hình lớn của máy tính là điều kiện vô cùng lý tưởng để quý đạo hữu đọc tụng các bộ kinh điển dài, tra cứu đại tạng kinh, mở nghe các bài Pháp thoại thanh tịnh khi đang làm việc, hoặc đặc biệt là thực hành công phu Chép Kinh trực tiếp bằng bàn phím để rèn luyện sự định tâm và chánh niệm.`,`Bạn chỉ cần dùng trình duyệt web quen thuộc (như Chrome, Edge, Safari...) truy cập vào địa chỉ của ứng dụng. Để thuận tiện mở app nhanh chóng mỗi ngày mà không cần mở nhiều tab trình duyệt, bạn có thể thực hiện thao tác cài pwa bằng cách nhấn vào biểu tượng cài đặt (hình dấu cộng hoặc màn hình nhỏ) ngay trên thanh địa chỉ của trình duyệt máy tính, ứng dụng sẽ được ghim ra màn hình Desktop như một phần mềm chuyên nghiệp.`,`Mọi dữ liệu công phu, danh sách bài đọc dở và dấu trang của bạn sẽ được đồng bộ liền mạch giữa máy tính và điện thoại khi đăng nhập cùng một tài khoản. Một vài tiện ích riêng biệt của thiết bị di động (như rung phản hồi chuỗi hạt hay widget màn hình khóa) sẽ chỉ khả dụng trên điện thoại, còn toàn bộ kho tàng kinh điển và công cụ tu tập đều sẵn sàng đồng hành cùng bạn trên máy tính mọi lúc mọi nơi.`],editorialStatus:`verified`}]}],i=[{id:`dung-web`,icon:`📱`,title:`General Guide`,shortTitle:`General Guide`,keywords:[`home`,`search`,`dark mode`,`night mode`,`epub`,`practice`,`reading`],editorialStatus:`verified-software`,introduction:[`Use Home, Scriptures, Practice, Talks and Profile to navigate. The steps below describe the current interface; some actions appear only for supported content or accounts.`],topics:[{id:`giao-dien-va-chuyen-dong`,title:`Appearance, language and text size`,keywords:[`motion effects`,`water ripples`,`reduced motion`,`font size`,`Giao diện, ngôn ngữ và cỡ chữ`,`Appearance, language and text size`],blocks:[{type:`steps`,items:[{title:`Open settings`,text:`Go to Profile → App Settings → Appearance & language. Choose Auto, White, Light beige, Gray, Light purple or Dark, and adjust interface text size.`},{title:`Change language`,text:`Select Tiếng Việt or English. When switching to English, let the English books finish downloading. If interrupted, check connection and storage, then choose Retry. Interface language does not mean every recording, cover or recipe is translated.`},{title:`Separate interface and reading sizes`,text:`Reading font size is independent of interface size. Use reading settings or the reader tools for font, size and paper background. Motion effects can be disabled; system Reduce Motion is respected.`}]}]},{id:`widget-man-hinh-chinh`,title:`Add a home-screen widget`,keywords:[`widget`,`calendar`,`Dharma audio`,`practice`,`home screen`,`Thêm widget lên màn hình chính`,`Add a home-screen widget`],blocks:[{type:`steps`,items:[{title:`Choose a widget`,text:`On Android, long-press a blank home-screen area and open Widgets. On iPhone/iPad, enter home-screen editing and open the widget picker. Find Tu Tập Phật Pháp and select an available Calendar, Practice or Dharma Audio widget and size.`},{title:`Open the relevant screen`,text:`Tap the widget content or action to open the corresponding app screen. Widgets use available data; open the app to set up or practise when data is missing. Opening a tool does not mark it complete.`},{title:`Understand refresh timing`,text:`The operating system schedules refreshes. A widget may not immediately reflect changes while the app is closed; it is not an alarm or proof that synchronization has finished.`}]}]},{id:`cap-nhat-noi-dung`,title:`Check and download content updates`,keywords:[`manual content update`,`new books`,`download size`,`Kiểm tra và tải cập nhật nội dung`,`Check and download content updates`],blocks:[{type:`steps`,items:[{title:`Open from Home`,text:`Find Content updates on Home and choose the check action. A connection is required; review the available content and download size before downloading.`},{title:`Watch the download status`,text:`Choose the desired updates and wait for completion. If the connection fails or storage is insufficient, resolve it and retry. Starting a download does not mean the content is available offline.`},{title:`Content is separate from the app version`,text:`Content updates do not replace App Store or Google Play updates. New features and fixes require the relevant app version.`}]}]},{id:`trang-chu-va-tim-kiem`,title:`Home and the reading library`,keywords:[`search articles`,`categories`,`karma`,`buddhist sutras`,`epub`,`Trang chủ và tìm kinh sách`,`Home and the reading library`],blocks:[{type:`steps`,items:[{title:`Use the navigation bar`,text:`Open Home, Scriptures, Practice, Talks or Profile. Home contains the lunar calendar, daily reminders, personal observances and a shortcut to the vegan meal calendar.`},{title:`Find a book`,text:`In Scriptures, search by title or open Filter. Select a book, open its contents and choose a chapter. Your library helps you return to reading and saved items.`},{title:`Continue reading`,text:`Open a recent book or bookmark to return to its saved chapter and position. The catalogue can differ between iOS, Android and the web; some content is only in Vietnamese.`}]}]},{id:`tu-tap-tren-web`,title:`Find a practice tool`,keywords:[`start practice`,`floating button`,`wooden fish`,`meditation music`,`auto scroll`,`Tìm công cụ trong trang Tu tập`,`Find a practice tool`],blocks:[{type:`steps`,items:[{title:`Choose an activity`,text:`Practice contains Continue Practice, the balanced vegan meal calendar, Practice routines, My Practice Journal, daily reflection and community access.`},{title:`Open the practice tools`,text:`Scroll to meditation, rosary beads, prostrations, sutra or sacred-name copying, precepts, Eight Precepts, restraint, sutras, mantras and rituals. Read the tool instructions before starting.`},{title:`Choose a text`,text:`In Recite Sutras, Chant Mantras or Other Rituals, choose a text and chapter. Read any guidance notice shown. Audio and translations are not available for every item.`}]}]},{id:`dong-bo-nut-quay-lai-android`,title:`Back navigation and closing panels`,keywords:[`back button`,`android gestures`,`swipe edge`,`exit book`,`table of contents`,`Quay lại và đóng bảng đang mở`,`Back navigation and closing panels`],blocks:[{type:`steps`,items:[{title:`Close the current layer first`,text:`Use Close or Back to dismiss a picker, tools panel or dialog before leaving a screen. Android Back participates in this flow; use the in-app back controls on iOS.`},{title:`End sessions deliberately`,text:`In beads, meditation, prostrations or routines, distinguish pausing from ending. Read confirmations and save status. Resolve save errors before clearing data or uninstalling.`}]}]},{id:`doc-offline-khong-can-mang`,title:`What works offline?`,keywords:[`offline`,`no internet`,`offline reading`,`airplane mode`,`cached`,`Nội dung nào dùng được khi ngoại tuyến?`,`What works offline?`],blocks:[{type:`steps`,items:[{title:`Bundled books and rituals`,text:`Content included in the app can open without a connection. Availability depends on platform and version; not every book, image, PDF, translation or video is bundled.`},{title:`Download what you need first`,text:`While online, use the supported document or album download action, wait for completion and reopen it to check. Unfinished PDF, audio or video downloads still need a connection. English books download separately apart from bundled rituals.`},{title:`Keep on-device data`,text:`Do not clear app data to fix a download. Unsynced copies, notes or practice records may exist only on that device; uninstalling or clearing browser data can remove them.`}]}]}]},{id:`doc-sach`,icon:`📖`,title:`Reading Books, PDFs & Quotations`,shortTitle:`Read Books`,keywords:[`pdf`,`two page`,`thumbnail`,`table of contents`,`sepia`,`highlight`,`notes`,`tts`,`offline`],editorialStatus:`verified-software`,introduction:[`Use the appropriate tools for text books, PDFs and recordings. Bundled content works offline; files not yet on the device must be downloaded first.`],topics:[{id:`doc-pdf`,title:`Open text books and PDFs`,keywords:[`two page`,`outline`,`thumbnail`,`zoom`,`fit screen`,`sepia`,`Mở sách văn bản và PDF`,`Open text books and PDFs`],blocks:[{type:`steps`,items:[{title:`Text books`,text:`Select a book in Scriptures, open its contents and choose a chapter. Use Tools to adjust reading. Returning from recent reading or a bookmark restores the saved position when that data is available.`},{title:`PDF documents`,text:`Open an item marked PDF and wait for it to load. Use page and zoom controls. Text-book font and size settings do not change the printed lettering inside a PDF page.`}]}]},{id:`chi-tiet-thanh-cong-cu-doc`,title:`Use the reading tools`,keywords:[`reader tools`,`font size`,`font family`,`bold`,`line height`,`paper background`,`bookmark`,`listen`,`share`,`download`,`auto scroll`,`Tùy chỉnh công cụ đọc`,`Use the reading tools`],blocks:[{type:`steps`,items:[{title:`Text and background`,text:`Open Reading Tools for A−/A+, font, bold text, line spacing and available paper backgrounds. These apply to text content; PDFs have separate controls.`},{title:`Navigate and save positions`,text:`Use the contents to change chapters and bookmarks to save and return to positions. Where the practice floating menu is available, ↑ Top and ↓ Bottom jump within the current text.`},{title:`Listen, scroll and share`,text:`Use text-to-speech or auto-scroll where supported. Speech depends on the device, language and text; it is separate from recorded Dharma talks. Share a link or export EPUB when the relevant action is available.`}]}]},{id:`ghi-chu-va-trich-dan`,title:`Notes and saved quotes`,keywords:[`highlight`,`annotation`,`personal notes`,`my quotes`,`save quote`,`Ghi chú và trích dẫn đã lưu`,`Notes and saved quotes`],blocks:[{type:`steps`,items:[{title:`Select a passage`,text:`In text content that supports selection, select a passage and use the available highlight, note or quote action. Check the saved text and destination before leaving.`},{title:`Return and share`,text:`Open Profile → Saved quotes. For quote images, preview the result before saving or sharing. On-device saving and account synchronization are different states; check the app status.`}]}]},{id:`pdf-nghe-va-offline`,title:`PDF downloads and text-to-speech`,keywords:[`tts`,`read aloud`,`offline save`,`indexeddb`,`Tải PDF và dùng đọc thành tiếng`,`PDF downloads and text-to-speech`],blocks:[{type:`steps`,items:[{title:`Save an offline PDF`,text:`For supported PDFs, start the download and wait until it completes. Reopen without a connection to check. Retry interrupted downloads instead of clearing app data.`},{title:`Understand speech limits`,text:`Text-to-speech needs readable text and a suitable device voice. Scanned image-only PDFs may not contain text to speak. Recorded Dharma audio is played or downloaded in Talks.`}]}]}]},{id:`cong-cu-tu-tap`,icon:`📿`,title:`Cultivation Tools & Practice Tracking`,shortTitle:`Practice`,keywords:[`rosary`,`mala beads`,`meditation`,`timer`,`goals`,`heatmap`,`group practice`],editorialStatus:`verified-software`,introduction:[`Choose a suitable tool, read its instructions and record the actual practice. Routines combine activities, while vegan menus help plan meals.`],topics:[{id:`che-do-le-phat`,title:`Prostrations and counting`,keywords:[`prostrations`,`repentance`,`Buddha statues`,`108 bows`,`21 bows`,`practice journal`,`Lễ Phật và ghi nhận số lạy`,`Prostrations and counting`],blocks:[{type:`steps`,items:[{title:`Set up`,text:`Open Practice → Prostrations & Repentance. Choose the sacred image, target and available options, read the guidance and begin when ready.`},{title:`Practise and finish`,text:`Use the counting input shown and check the recorded count. Pause or finish as needed and record actual prostrations. In a routine, finishing a step continues the routine without filling an unmet target.`}]}]},{id:`che-do-thanh-tinh`,title:`Restraint practice and private journal`,keywords:[`self restraint`,`Thanh Tinh`,`Buddha recitation`,`mantra`,`wooden fish`,`bell`,`Tiết dục bảo thân và nhật ký riêng`,`Restraint practice and private journal`],blocks:[{type:`steps`,items:[{title:`Open the tool`,text:`Choose Practice → Sexual Restraint & Well-being, read the guidance and choose what to track. It supports reflection and habits; seek professional help when health support is needed.`},{title:`Understand storage`,text:`Use the visible controls for streaks, resisted urges and writing. The private journal stays on the device and is not automatically synchronized like progress counters. Check sharing options before submitting content.`}]}]},{id:`cai-dat-nhac-nho-tu-tap`,title:`Set reminders and personal observances`,keywords:[`practice reminders`,`lunar calendar`,`vegetarian days`,`Buddhist observances`,`morning practice`,`evening practice`,`Cài lời nhắc và ngày lễ cá nhân`,`Set reminders and personal observances`],blocks:[{type:`steps`,items:[{title:`Open reminder settings`,text:`In Profile → App Settings, open Lunar calendar & observances for fasting days, Tho Khang Bao Giam and Buddhist observances. Set reminder times and available advance/on-day options.`},{title:`Add a personal date`,text:`Use Personal observances on Home or in Settings. Enter a name, choose lunar/Gregorian dates and reminder options. Check the current-year conversion, especially lunar dates and leap months.`},{title:`Check system permissions`,text:`Grant notification permission when needed. Review iOS Settings → Notifications; Android may also ask for Alarms & reminders. Battery restrictions, Focus and system settings can delay or hide notifications; exact delivery is not guaranteed in every situation.`}]}]},{id:`chep-kinh-tren-app`,title:`Sutra copying: choose, type and save`,keywords:[`sutra copying`,`type scripture`,`draft`,`Chép kinh: chọn nguồn, tự gõ và lưu`,`Sutra copying: choose, type and save`],blocks:[{type:`steps`,items:[{title:`Choose a sutra`,text:`Open Practice → Sutra copying, choose Ksitigarbha, Lotus or Surangama and a chapter/volume. Open the guide, read it and continue to the copying screen.`},{title:`Use the reference`,text:`Select a passage in Reference text and use previous/next, text-size options or collapsed controls. The reference follows typing where supported. Enable Faded Text if desired and type in Your copy.`},{title:`Review and save`,text:`Use Review to inspect possible issues; it is a reference check, not an automatic rewrite. Drafts are saved on the device. To save in the account, sign in, choose Save to system and check the result. Uninstalling or clearing data can remove local-only copies.`}]}]},{id:`trang-hat-ao`,title:`Rosary beads: manual and automatic counting`,keywords:[`digital rosary`,`mala`,`automatic rhythm`,`wooden fish`,`108 beads`,`20 bpm`,`30 bpm`,`40 bpm`,`60 bpm`,`80 bpm`,`Lần tràng hạt: đếm tay và nhịp tự động`,`Rosary beads: manual and automatic counting`],blocks:[{type:`steps`,items:[{title:`Open a session`,text:`Choose Practice → Rosary Beads, read the introduction and select Begin. In Options, choose a recitation, bead count, target and available sound settings.`},{title:`Count manually`,text:`Tap or swipe the beads, or choose Count one bead. On a keyboard, use the indicated key. Review the current count, beads in the strand and completed strands.`},{title:`Use automatic rhythm`,text:`Open the automatic-rhythm options, set the pace and start it when needed. Distinguish pause, stop, reset and end-session actions; read the confirmation before resetting. Finish with actual counts, not an assumed completed target.`}]}]},{id:`so-quan-chieu-ca-nhan`,title:`Daily reflection and private writing`,keywords:[`reflection journal`,`private diary`,`good deeds`,`nickname`,`body speech mind`,`Quán chiếu và ghi chép riêng tư`,`Daily reflection and private writing`],blocks:[{type:`steps`,items:[{title:`Open reflection`,text:`In Practice, choose Reflect on today’s good and unwholesome deeds. Read the guide and reflect on actions, areas to improve and the next practice.`},{title:`Choose the destination`,text:`Private saving and community sharing are different choices. Share only when you intend to disclose that content. Avoid other people’s sensitive information; a private journal is not automatically a public post.`}]}]},{id:`cong-dong-sam-hoi-tuy-hy`,title:`Community and privacy`,keywords:[`community`,`repentance`,`rejoicing`,`prayer`,`encouragement`,`my posts`,`Cộng đồng và quyền riêng tư`,`Community and privacy`],blocks:[{type:`steps`,items:[{title:`Choose to participate`,text:`Open Join Community or the community practice area, read a goal’s conditions and join if desired. Use the relevant tool. Only eligible sessions contribute under that goal’s rules.`},{title:`Manage visibility`,text:`Check sharing, leaderboard and active-practice privacy choices. Pending comments or profiles may not yet be public. Use content or member menus to report or block.`}]}]},{id:`khoa-le-hang-ngay`,title:`Create and follow a practice routine`,keywords:[`daily routine`,`prostrations`,`meditation`,`mala`,`custom dedication`,`Tạo và thực hành thời khóa`,`Create and follow a practice routine`],blocks:[{type:`steps`,items:[{title:`Create a routine`,text:`Open Practice → Practice routines → Create a routine. Name it and use Add step; at least two steps are required. Available activities include vows and repentance, meditation, beads, prostrations, both copying tools, precepts, Eight Precepts, restraint, sutras, mantras, rituals and dedication.`},{title:`Configure the steps`,text:`Expand a step to choose its content and target. Move it up/down or remove it. Select the required text for readings and copying, then save the routine.`},{title:`Follow the sequence`,text:`Open the saved routine and start. Pause as needed. Finishing a step continues to the next even if its target was not met. Records keep actual counts and duration; targets are not filled automatically. Check save status before leaving.`}]}]},{id:`dong-bo-ca-nhan-48-gio`,title:`Understand practice saving and synchronization`,keywords:[`48 hours`,`personal sync`,`dedication`,`restore routines`,`data savings`,`Hiểu trạng thái lưu và đồng bộ công phu`,`Understand practice saving and synchronization`],blocks:[{type:`steps`,items:[{title:`On-device saving`,text:`The app stores practice data according to each tool. Check My Practice Journal or progress. Copies, private journals, downloaded files and practice records do not all use the same saving mechanism.`},{title:`Account synchronization`,text:`Sign in with the same account and connect to synchronize supported data. Some updates are grouped or queued; a 48-hour interval is not proof that everything reached the server. Check status and retry reported failures.`},{title:`Before changing devices`,text:`Use Save to system for copies you want stored in the account. Keep the old device data until required records are confirmed saved; offline files and private journals may not be restored on a new device.`}]}]},{id:`toa-thien-hen-gio`,title:`Guided meditation and Focus mode`,keywords:[`meditation timer`,`mindfulness bell`,`sitting practice`,`Thiền có hướng dẫn và chế độ Tập trung`,`Guided meditation and Focus mode`],blocks:[{type:`steps`,items:[{title:`Set up first`,text:`Open Practice → Meditation. Choose a duration in Time and review Music, Ambient sound and Background tabs. Motion sensing is optional and is not required to record meditation.`},{title:`Start a session`,text:`Select Start meditation. The setup describes preparation time and opening/closing bells. Check volume, silent mode and device permissions if audio is missing. Follow the session timer; bells are not guaranteed alarms when the OS restricts the app.`},{title:`Enter and leave Focus`,text:`During a session, choose Focus for a lotus and breathing guidance. Use Exit Focus at the top or supported back navigation to return to controls; the session clock continues. Pausing and ending are separate actions.`}]}]},{id:`goi-y-va-tien-do`,title:`Calendar, practice records and titles`,keywords:[`lunar calendar`,`vegetarian days`,`streak`,`heatmap`,`merit dedication`,`Lịch, công phu và danh hiệu tu tập`,`Calendar, practice records and titles`],blocks:[{type:`steps`,items:[{title:`Read the calendar`,text:`Home shows lunar/Gregorian dates, a week strip and a month-calendar action. Select a date for its information. Daily reminders do not mark a practice complete.`},{title:`Review practice`,text:`Open My Practice Journal or Profile → Practice progress for day, week, month and year views and activity details. Use manual recording for practice outside the app where available.`},{title:`Badges and titles`,text:`Home and Account show practice identity from the account’s practice data. Account labels the Practice title. Missing data is different from achieving a rank; check connection and account if synchronization is unfinished.`}]}]},{id:`an-chay-thuc-don-cong-thuc`,keywords:[`Ăn chay: thực đơn, công thức và đi chợ`,`Vegan meals, recipes and shopping`],title:`Vegan meals, recipes and shopping`,blocks:[{type:`steps`,items:[{title:`Open a menu`,text:`Open the balanced vegan meal calendar from Home or Practice. In Today, set servings and choose All, North, Central or South. Changing region can change suggested dishes.`},{title:`Read a recipe`,text:`Select View beside a dish. Check time, ingredients and cooking steps. Adjust servings or A−/A+ text size. Resting, soaking and steaming times do not necessarily scale with servings. Dish names and recipes may remain Vietnamese in the English interface.`},{title:`Plan shopping`,text:`Open Week & shopping for daily planning and shopping information. Today’s ingredients summarizes the current day. Dish menu searches beyond the suggestions. Check ingredients, allergies and household portions; nutrition information is for reference.`},{title:`Use offline`,text:`Bundled or previously downloaded menus and recipes work offline. Check and download new weekly content while connected. Not every recipe has a photo or video.`}]}]},{id:`chep-danh-hieu-tren-app`,keywords:[`Chép danh hiệu Phật, Bồ Tát`,`Copy Buddha and Bodhisattva names`,`chép danh hiệu`,`sacred names`,`sacred-name copying`],title:`Copy Buddha and Bodhisattva names`,blocks:[{type:`steps`,items:[{title:`Choose a name`,text:`Open Copy Buddha and Bodhisattva Names in Practice. Choose the name, read the guide and type in the copying area, following the actual count.`},{title:`Save and return`,text:`Check save status and use account saving where offered or required. If opened from a routine, use that flow’s return controls to continue. A target of 108 names is not a completed count.`}]}]},{id:`giu-gioi-va-bat-quan-trai`,keywords:[`Giữ giới và Thọ Bát quan trai`,`Precept Practice and Eight Precepts`],title:`Precept Practice and Eight Precepts`,blocks:[{type:`steps`,items:[{title:`Precept Practice`,text:`Open Practice → Precept Practice to read and reflect on the Five Precepts and Ten Wholesome Actions. Follow the recording controls; entries are personal reflections, not certification by a teacher.`},{title:`Eight Precepts`,text:`Open Eight Precepts, read the guidance and rite, check the period and make a personal commitment when ready. Follow the day-and-night practice instructions; the app does not replace guidance from the Sangha or a responsible teacher.`}]}]}]},{id:`phap-thoai`,icon:`🎧`,title:`Dharma Talks & Audio Lectures`,shortTitle:`Dharma Talks`,keywords:[`audio`,`persistent player`,`favorites`,`listen later`,`speaker`,`duration`],editorialStatus:`verified-software`,introduction:[`Find an album, choose a track and use the existing player. Video and offline downloads are available only for supported content; recording language varies.`],topics:[{id:`dieu-khien-phap-thoai`,title:`Listen to talks and watch video`,keywords:[`mini player`,`rewind 10s`,`forward 30s`,`media session`,`lockscreen`,`Nghe pháp thoại và xem video`,`Listen to talks and watch video`],blocks:[{type:`steps`,items:[{title:`Choose an album and track`,text:`Open Talks, search or use Search and filters; use Top 10 for the corresponding list. Open an album and choose a track. Supported video albums carry a Video label.`},{title:`Control playback`,text:`Use play/pause, seeking and track selection in the player. Resume Listening restores available saved progress. The mini-player returns to the current track across screens without starting a second track.`},{title:`Use full screen`,text:`For supported video, open full screen. Controls hide during playback and reappear on a tap, staying visible while paused, loading or interacting. After seeking, allow audio/video to reload; streaming requires a connection.`}]}]},{id:`luu-va-loc-phap-thoai`,title:`Find and download talks for offline use`,keywords:[`favorites`,`listen later`,`recent`,`speaker`,`duration`,`Tìm lại và tải pháp thoại ngoại tuyến`,`Find and download talks for offline use`],blocks:[{type:`steps`,items:[{title:`Find content again`,text:`Use search, filters, sorting and available recent/favourite lists. Titles, catalogue and language depend on the album; selecting English does not translate a Vietnamese recording.`},{title:`Download supported tracks`,text:`Use the download action, sign in if requested and wait for completion. Check the status and reopen offline. Interrupted downloads, missing files or insufficient space can prevent offline playback.`},{title:`Background playback`,text:`Background and lock-screen controls depend on platform, content type and device settings. Video and embedded sources may have separate limits; not every source supports downloading or background playback.`},{title:`Listen later`,text:`Use the album bookmark icon to add or remove it from Listen Later. Open Listen Later to find selected albums. Bookmarking does not download audio files.`}]}]}]},{id:`tai-khoan-dong-bo`,icon:`☁️`,title:`Account Sync & Cloud Storage`,shortTitle:`Cloud Sync`,keywords:[`google login`,`cloud sync`,`backup`],editorialStatus:`verified-software`,introduction:[`Sign in for supported account and synchronization features. Distinguish device-only data, account-saved data and public content.`],topics:[{id:`an-toan-cong-dong`,title:`Report, block and manage community content`,keywords:[`report`,`block`,`unblock`,`community`,`moderation`,`Báo cáo, chặn và quản lý nội dung cộng đồng`,`Report, block and manage community content`],blocks:[{type:`steps`,items:[{title:`Report content`,text:`Open a comment, reply or member menu, choose Report and provide the reason. Identify the relevant content without publicly exposing another person’s private information.`},{title:`Block and review privacy`,text:`Use Block to limit a member in supported community areas. Review blocked accounts and sharing choices in Settings. Pending and rejected content have separate statuses and are not equivalent to public posts.`}]}]},{id:`xoa-tai-khoan`,title:`Sign out and delete an account`,keywords:[`delete account`,`Apple`,`confirmation code`,`data`,`Đăng xuất và xóa tài khoản`,`Sign out and delete an account`],blocks:[{type:`steps`,items:[{title:`Find account actions`,text:`Open Profile → Account while signed in. Choose Sign out to end the device session. Choose Delete account only when you intend the deletion described in the app confirmation.`},{title:`Read before confirming`,text:`Account deletion can remove account-linked data under the policy. Signing out, uninstalling or deleting a downloaded file is not account deletion. If an error occurs, check the status rather than assuming completion.`}]}]},{id:`ket-noi-facebook-quan-tri`,title:`Facebook connection for administrators`,keywords:[`Facebook connect`,`Meta app review`,`user_posts`,`import source`,`ledger`,`reconnect`,`Kết nối Facebook dành cho quản trị`,`Facebook connection for administrators`],blocks:[{type:`steps`,items:[{title:`Separate it from sign-in`,text:`Facebook connection or content import is an administrative tool where authorized. It is not a Facebook sign-in instruction for the native app. Regular users do not need it.`},{title:`Use the authorized interface`,text:`Follow the actions and permissions actually shown in administration. Do not paste tokens or login details into comments or community support. Contact the administrator if the tool is unavailable.`}]}]},{id:`dang-nhap-va-dong-bo`,title:`Sign in and keep supported data across devices`,keywords:[`google login`,`practice history`,`notes`,`reading progress`,`Đăng nhập và giữ dữ liệu giữa các thiết bị`,`Sign in and keep supported data across devices`],blocks:[{type:`steps`,items:[{title:`Sign in when needed`,text:`Public reading, listening and many practice tools are available as a guest. Open Profile → Account and use an available provider. Native apps offer Google or Apple as applicable; do not expect a Facebook button where none is shown.`},{title:`Use the same account`,text:`On another device, choose the same provider and account. Check the profile and synchronization status. Signing in does not prove every local draft, private journal or downloaded file from the old device was uploaded.`},{title:`If reauthentication is needed`,text:`Restore the connection and retry as instructed. Preserve unfinished local data before clearing anything. Signing out and deleting an account are different actions; read their confirmations.`}]}]}]}],a=[{id:`huong-dan-nguoi-moi`,icon:`🌱`,title:`Beginner’s 4-Stage Guide to Buddhist Practice`,shortTitle:`Beginners`,keywords:[`beginners`,`starting practice`,`four stages`,`karma`,`reincarnation`,`great compassion mantra`,`earth store sutra`],editorialStatus:`verified`,introduction:[`Beginning Buddhist study and daily cultivation can feel overwhelming with countless scriptures, commentaries, and traditions. A grounded, step-by-step path rooted in Right View helps you build unshakeable faith, purify karmic hindrances, and cultivate tangible peace in daily living.`,`Below is the 4-stage foundation tailored for beginners: from understanding the reality of cause and effect through books, establishing daily mantra recitation, deepening wisdom through ancestral commentaries, to dedicating oneself to a lifelong steadfast practice.`],topics:[{id:`giai-doan-1-doc-sach-nhan-qua-luan-hoi`,title:`Stage 1 — Understanding the Law of Karma & Reincarnation`,keywords:[`stage 1`,`karma books`,`retribution in this life`,`many lives many times`,`cause and effect`],blocks:[{type:`callout`,tone:`note`,title:`First Foundation: Developing Right Faith in the Law of Karma`,text:`The Buddha taught: “To know your past causes, look at what you receive in this life; to know your future fruits, look at what you sow in this life.” For newcomers, theoretical abstractions are secondary. First, examine modern real-life karmic accounts to awaken profound faith in karma and rebirth, naturally leading to refraining from unwholesome deeds and cultivating goodness.`},{type:`steps`,items:[{title:`Read the Complete “Karmic Retributions in Modern Times” Series (Vol 1–8)`,text:`Chronicles compiled by Upasaka Guo Qing under Venerable Master Miao Fa. Real modern accounts reveal the hidden karmic roots behind incurable illnesses, family discord, and sudden bankruptcy—tracing back to killing, abortion, sexual misconduct, theft, or filial impiety. Reading this strikes the heart and inspires a firm resolve to halt all evil actions.`},{title:`Read “The Mission of Guiding the Departed” (Sứ Mệnh Độ Vong)`,text:`Offers compassionate insight into the unseen realm and consciousness after death. Understand the plight of aborted spirits and karmic creditors, transforming baseless fear or superstition into genuine compassion through prayer, chanting, and merit dedication.`},{title:`Read “An Shi Quan Shu” (An Sỹ Toàn Thư)`,text:`A celebrated classic on cause and effect by Upasaka Zhou Anshi, highly praised by Master Yin Guang. It systematically explains karmic consequences, inspiring wholesome conduct and pure moral discipline.`},{title:`Listen to Audio Lectures on Karma & the Afterlife`,text:`Utilize quiet hours or commutes to listen to cautionary karmic lectures and near-death experiences in the Dharma Talks section, deepening confidence in the unseen moral order.`}]},{type:`bullets`,title:`Goals Achieved After Stage 1:`,items:[`Eradicating doubts regarding karma, rebirth, and the unseen moral law.`,`Adopting a vegetarian diet, reducing harm to sentient beings, liberating captive lives, honoring parents, and speaking gently.`,`Deeply realizing the fleeting nature of life and cultivating a sincere yearning for Dharma practice.`]}]},{id:`giai-doan-2-hang-ngay-tri-tung-chu-dai-bi`,title:`Stage 2 — Daily Recitation of the Great Compassion Mantra`,keywords:[`stage 2`,`daily practice`,`great compassion mantra`,`earth store sutra`,`purifying karma`],blocks:[{type:`callout`,tone:`note`,title:`Commencing Practical Cultivation: The Power of Great Compassion Dharani`,text:`The Great Compassion Dharani is the sacred heart mantra of Bodhisattva Avalokiteshvara, possessing unfathomable power to dissolve karmic obstacles, heal grievances, and shield body and mind. Regular recitation quickly settles scattered thoughts, dispels anxiety, and brings profound inner tranquility.`},{type:`steps`,items:[{title:`Daily Recitation in the Practice Section`,text:`Commit to reciting the Great Compassion Mantra at least 5, 7, 21, or 108 times daily. Use the built-in wooden fish sound and mala beads to sustain rhythmic focus.`},{title:`Study Master Hsuan Hua’s Commentary on the Earth Store Sutra`,text:`Listen to Venerable Master Hsuan Hua’s clear, accessible explanation of the Earth Store Sutra, clarifying filial piety, karmic retribution, and the immense vows of Ksitigarbha Bodhisattva.`}]}]},{id:`giai-doan-3-sau-6-thang-nghe-kinh-phap-hoa`,title:`Stage 3 — Deepening Wisdom with the Lotus Sutra Commentary`,keywords:[`stage 3`,`lotus sutra`,`hsuan hua`,`wisdom`,`buddha nature`],blocks:[{type:`paragraph`,text:`After steady cultivation for 6 months to a year, listen to Master Hsuan Hua’s commentary on the Lotus Sutra (Saddharma Pundarika Sutra)—the King of Sutras that reveals all sentient beings possess inherent Buddha-nature.`}]},{id:`giai-doan-4-dinh-hinh-phap-mon-chuyen-tu`,title:`Stage 4 — Establishing a Steadfast Lifelong Practice`,keywords:[`stage 4`,`lifelong practice`,`pure land`,`nembutsu`,`chan`,`vows`],blocks:[{type:`paragraph`,text:`Ground your practice firmly in a specific Dharma gate—whether Pure Land mindfulness of Amitabha Buddha, Shurangama Mantra recitation, or Earth Store repentance—persisting daily until liberation.`}]}]},{id:`huong-dan-tung-kinh`,icon:`📖`,title:`Guide to Sutra Chanting`,shortTitle:`Sutra Chanting`,keywords:[`sutra chanting`,`morning practice`,`evening practice`,`pregnancy`,`dreams`,`illness`,`earth store sutra`],editorialStatus:`verified`,introduction:[`Chanting sutras involves reciting the Buddha’s sacred words with reverent mindfulness, nurturing understanding, expanding wisdom, and planting wholesome seeds with the Three Jewels.`],topics:[{id:`thoi-gian-tung-kinh`,title:`Ideal Times for Sutra Chanting`,keywords:[`chanting schedule`,`morning`,`evening`,`vegetarian days`],blocks:[{type:`cards`,items:[{title:`Daily Practice is Best`,text:`If daily recitation is difficult, practice once a week or on lunar observance days (1st, 8th, 14th, 15th, 23rd, 30th of the lunar month) while keeping precepts.`},{title:`Early Morning or Before Sleep`,text:`The mind is clearest at these hours. Morning chanting inspires pure intentions for the day; evening chanting purifies regrets and calms the spirit.`}]}]},{id:`hoan-canh-nen-tung-kinh-dia-tang`,title:`Occasions for Chanting the Earth Store Sutra`,keywords:[`earth store sutra`,`pregnancy`,`nightmares`,`departed loved ones`,`serious illness`,`adversity`],blocks:[{type:`steps`,items:[{title:`During Pregnancy or Before Childbirth`,text:`Recite the Earth Store Sutra and chant Ksitigarbha’s holy name 10,000 times to dispel ancestral karma and bless the newborn with peaceful longevity.`},{title:`Nightmares or Seeing the Departed in Dreams`,text:`Often indicates departed relatives seeking wholesome merits. Dedicate 3 to 7 recitations of the Earth Store Sutra for their liberation.`},{title:`Severe Family Illness`,text:`Chanting on behalf of an ailing person or sponsoring sutra distributions helps eradicate weighty karma and ease distress.`},{title:`Within 49 Days of a Passing`,text:`During the 49-day bardo state, dedicate sincere recitations to assist the departed soul into a peaceful rebirth.`},{title:`Facing Hardships & Major Obstacles`,text:`Commit to a 7-day, 21-day, or 49-day recitation vow with 1,000 daily repetitions of Ksitigarbha Bodhisattva’s sacred name.`}]}]},{id:`luu-y-khi-tung-kinh`,title:`Mindful Guidelines for Chanting`,keywords:[`guidelines`,`sincerity`,`reverence`,`dedication`],blocks:[{type:`bullets`,title:`Essential points to remember:`,items:[`Chant clearly, steadily, and reverently—depth of mindfulness matters far more than speed.`,`An altar is not strictly required—any clean, quiet, and respectful space is suitable.`,`In public or crowded places, recite silently in your heart.`,`Cleanse your hands, rinse your mouth, and dress modestly before opening the scriptures.`,`Always conclude by dedicating all accumulated merits to all sentient beings.`]}]}]},{id:`huong-dan-tri-chu`,icon:`📿`,title:`Guide to Mantra Recitation (Dharani)`,shortTitle:`Mantra`,keywords:[`mantra`,`dharani`,`recitation`,`pure land`,`great compassion mantra`,`shurangama mantra`],editorialStatus:`verified`,introduction:[`A Mantra (Dharani) embodies the mystic syllables of Buddhas and Bodhisattvas, functioning as an armor for body and mind to eliminate karma and awaken inner wisdom.`],topics:[{id:`phan-biet-tri-va-niem-chu`,title:`Reciting from Memory vs. Reading Mantras`,keywords:[`memorization`,`mindful chanting`],blocks:[{type:`cards`,items:[{title:`Holding Mantras (Trì Chú)`,text:`Reciting fluently from memory in continuous cycles. This represents formal core cultivation.`},{title:`Reading Mantras (Niệm Chú)`,text:`Chanting while reading text. Sincere devotion still yields immense, inconceivable merit.`}]}]},{id:`tri-chu-va-niem-phat-ket-hop`,title:`Combining Mantra Recitation with Buddha Mindfulness`,keywords:[`primary practice`,`supportive practice`,`pure land`,`amitabha`],blocks:[{type:`steps`,items:[{title:`Buddha Mindfulness as Primary Practice`,text:`If aspiring for Western Pure Land, recite "Namo Amitabha Buddha" as your core foundation.`},{title:`Mantras as Supportive Cultivation`,text:`Reciting the Great Compassion or Shurangama Mantra helps dissolve karmic obstructions and stabilizes the mind.`}]}]}]},{id:`tho-tuong-tai-gia`,icon:`🪔`,title:`Setting Up an Altar & Sacred Statues at Home`,shortTitle:`Altar Setup`,keywords:[`buddhist altar`,`statues`,`ksitigarbha`,`respectful placement`,`home worship`],editorialStatus:`verified`,introduction:[`Setting up a Buddhist altar at home can be done sincerely by yourself. Direct devotion and genuine respect yield pure, complete merit for the entire household.`],topics:[{id:`buoc-1-tam-tuong-khi-nhan-ve`,title:`Step 1 — Cleansing the Sacred Statue`,keywords:[`cleansing statue`,`pure water`,`respectful handling`],blocks:[{type:`steps`,items:[{title:`Prepare Dedicated Utensils`,text:`Prepare pure warm water, fragrant herbs/cleansing essence, a dedicated clean basin, and a fresh clean towel.`},{title:`Receive with Both Hands`,text:`Hold the sacred statue with both hands and reverent mind. Gently cleanse the image and dry it with the dedicated cloth.`},{title:`Store Utensils Respectfully`,text:`Keep these utensils in a clean place exclusively for future statue cleanings.`}]}]},{id:`buoc-2-an-vi-tuong-va-doc-bai-thinh`,title:`Step 2 — Enshrining the Statue & Sincere Invocation`,keywords:[`enshrining`,`altar placement`,`prayers`],blocks:[{type:`steps`,items:[{title:`Altar Placement`,text:`Place the statue on a clean, elevated altar. If sharing an altar with ancestors or guardian deities, the Buddha/Bodhisattva must be elevated higher.`},{title:`Chant Great Compassion Mantra`,text:`Recite 7 to 21 recitations of the Great Compassion Mantra with pure devotion.`},{title:`Read the Invocation Prayer (3 Times)`,text:`Sincerely recite the prayer inviting the Bodhisattva’s compassionate presence to guide your family toward wholesome virtues.`},{title:`7 Days of Dedicated Sutra Recitation`,text:`For the next 7 days, recite the Earth Store Sutra or Amitabha Sutra once daily to consecrate the home altar.`}]}]}]},{id:`thuc-hanh-hang-ngay`,icon:`📋`,title:`Daily Cultivation Routine & Living Mindfully`,shortTitle:`Daily Practice`,keywords:[`daily routine`,`morning vow`,`daytime virtue`,`evening repentance`,`core principles`],editorialStatus:`verified`,introduction:[`A regular, mindful daily routine steadily transforms karmic tendencies and establishes enduring peace for yourself and your family.`],topics:[{id:`khung-thoi-khoa-trong-ngay`,title:`Daily Practice Schedule`,keywords:[`morning`,`daytime`,`evening`,`repentance`,`merit dedication`],blocks:[{type:`steps`,items:[{title:`Morning — Awakening Wholesome Intentions`,text:`Upon waking, spend 5 minutes reciting holy names and renew your vow: "Today I resolve to do good, refrain from evil, help sentient beings, and maintain a pure heart." Then chant your morning session.`},{title:`Daytime — Practicing Kindness & Silent Chanting`,text:`Help others in small, practical ways. Use idle moments while walking, commuting, or cooking to silently repeat the Buddha’s name.`},{title:`Evening — Repentance & Merit Dedication`,text:`Before sleep, reflect upon the day. Acknowledge mistakes with sincere repentance, and dedicate all day’s merits to all living beings.`}]}]},{id:`nguyen-tac-cot-loi`,title:`Core Cultivation Principles`,keywords:[`consistency`,`sincerity`,`five precepts`,`patience`],blocks:[{type:`bullets`,items:[`Consistency is paramount — 15 mindful minutes every day is far superior to 3 hours once a week.`,`Sincere heart outweighs mere form — 5 minutes of focused chanting surpasses an hour of distracted recitation.`,`Ethical foundation: Uphold the Five Precepts (no killing, stealing, sexual misconduct, lying, or intoxicants).`,`Patience and perseverance — Dharma cultivation is a lifelong cultivation, not a rapid pursuit of results.`]}]}]},{id:`bo-thi-may-nghe-phap`,icon:`📻`,title:`Dharma Giving — Offering Recitation Players`,shortTitle:`Dharma Giving`,keywords:[`Dharma giving`,`recitation player`,`memory card`,`MicroSD`,`FAT32`,`spirits`],editorialStatus:`verified`,introduction:[`“Dharma giving surpasses all giving” (Dhammapada, verse 354). Offering recitation players shares teachings and Buddha-name recitation with a compassionate intention.`],topics:[{id:`y-nghia-va-cong-duc-phap-thi-may-nghe-phap`,title:`Meaning & Intention of Offering Recitation Players`,keywords:[`Dharma giving`,`merit`,`Buddha recitation`],blocks:[{type:`paragraph`,text:`Offering a Dharma or Buddha-recitation player is a way to share the teachings. Approach it with compassion, without fear, personal gain or requests for wealth from spirits.`}]},{id:`chuan-bi-may-va-the-nho-nghe-phap`,title:`Prepare a Player & Memory Card`,keywords:[`memory card`,`4GB`,`FAT32`,`MicroSD`],blocks:[{type:`callout`,tone:`note`,title:`Choose a player with a memory-card slot`,text:`Some inexpensive players contain fixed recordings and cannot accept new files. Choose a model with a MicroSD/TF slot or USB input that supports copying your selected audio.`},{type:`steps`,items:[{title:`Choose the player`,text:`Check the supported audio format, memory capacity, power supply and intended indoor or outdoor use.`},{title:`Prepare a 4GB MicroSD card`,text:`The existing guide uses a 4GB MicroSD card formatted as FAT32. Check compatibility with the chosen player before copying files.`},{title:`Set repeat playback`,text:`Insert the card and use Mode or Repeat to choose one-track or whole-list repetition, following the device instructions.`}]}]},{id:`vi-tri-dat-may-va-cach-che-chan-ngoai-troi`,title:`Placement & Weather Protection`,keywords:[`outdoor`,`weather`,`cemetery`,`volume`],blocks:[{type:`paragraph`,text:`Choose a suitable location only with the permission of the site’s owner or manager. Keep the player dry and ventilated, protect it appropriately for its rated use, and check it periodically.`},{type:`paragraph`,text:`Secure it safely and keep the sound gentle, audible within about 3–5 metres as suggested in the original guide. Respect nearby residents and visitors; do not obstruct walkways or disturb the site.`}]},{id:`tam-luong-va-nghi-thuc-khan-nguyen`,title:`Compassionate Intention & Dedication`,keywords:[`compassion`,`prayer`,`dedication`],blocks:[{type:`paragraph`,text:`Keep a sincere, compassionate intention rather than seeking personal gain. Dedicate the merit of your daily practice to the beings you wish to benefit.`},{type:`paragraph`,text:`Check the battery, clean the case and recharge when necessary.`}]},{id:`tai-ve-cac-bai-phap-tuyen-chon-cho-the-nho`,title:`Download the Selected Audio for a Memory Card`,keywords:[`download`,`memory card`,`Google Drive`,`extract`],blocks:[{type:`bullets`,title:`Original titles in the selected archive`,items:[`1. Kinh Địa Tạng Bồ Tát Bổn Nguyện (Diễn đọc trọn bộ) — bộ kinh căn bản độ âm thù thắng.`,`2. Thần Chú Tôn Thắng Phật Đảnh Đà La Ni (21 biến) — oai lực đệ nhất tiêu trừ ác nghiệp, cứu bạt địa ngục.`,`3. Bài khai thị cho Hương Linh, Vong Linh (Cửu Huyền Thất Tổ).`,`4. Lời khai thị cho người sắp lâm chung.`,`5. Nam Mô Địa Tạng Vương Bồ Tát (Thầy Thích Trí Thoát tụng).`,`6. Kinh Phổ Môn Diễn Đọc (Quán Thế Âm Bồ Tát cứu khổ cứu nạn).`,`7. Nam Mô Quan Thế Âm Bồ Tát.`,`8. Kinh A Di Đà diễn đọc.`,`9. Nam Mô A Di Đà Phật (bản mới trang nghiêm thanh tịnh).`,`10. Kinh Đại Thừa Vô Lượng Thọ (HT. Thích Đức Niệm dịch).`,`11. Tán Thán Phật A Di Đà Và Cõi Cực Lạc.`,`12. Kinh Quán Vô Lượng Thọ Phật.`,`13. Quê Hương Cực Lạc (Hòa thượng Tuyên Hóa khai thị).`,`14. Kinh Nghiệp Báo Sai Biệt.`,`15. Kinh Nhân Quả Ba Đời.`,`16. Diễn đọc Kinh Thập Thiện Nghiệp Đạo.`,`17. Kinh Dược Sư Lưu Ly Quang Như Lai Bổn Nguyện Công Đức.`,`18. Nam Mô Dược Sư Lưu Ly Quang Vương Phật (Thầy Thích Trí Thoát tụng).`,`19. Kinh Hoa Nghiêm — Phẩm Phổ Hiền Hạnh Nguyện.`,`20. Phẩm 5: Diệt Trừ Nghiệp Chướng (Kinh Ánh Sáng Hoàng Kim).`,`21. Kinh Đại Bi Tâm Đà La Ni.`,`22. Chú Đại Bi tiếng Phạn 21 biến (Quang Từ).`,`23. Kinh Đại Thừa Trang Nghiêm Bảo Vương.`,`24. Om Mani Padme Hum (Lục Tự Đại Minh Chú).`,`25. Kinh Phật Đảnh Tôn Thắng Đà Ra Ni.`,`26. Kinh Đại Thừa Công Đức Tạo Tượng Phật và Phát Bồ Đề Tâm Văn.`,`27. Kinh Phước Báo Của Tạo Lập Hình Tượng Phật.`,`28. Kinh Quán Thế Âm Bồ Tát Thọ Ký.`,`29. Diễn đọc Phật Thuyết Kinh Từ Thị Bồ Tát Đại Thành Phật.`]},{type:`steps`,items:[{title:`Download and extract`,text:`Open the author’s Google Drive archive below and download it to a computer or phone. Extract the archive to obtain its MP3 files.`},{title:`Copy to the card`,text:`Format the compatible 4GB card as FAT32 and copy the extracted MP3 files to the card’s root folder. Insert it in the player and check playback.`},{title:`Ask for help if needed`,text:`A phone or computer shop can help download, extract and copy the files. Share the archive link rather than account credentials.`}]},{type:`link`,href:`https://drive.google.com/file/d/1QSNeYvzkTMsNorQ_23b3W1TIYrQekYeH/view?usp=sharing`,externalActions:!0,label:`Download the selected Dharma audio archive`,text:`The author’s existing Google Drive archive; download and extract the files before copying them to the card.`,buttonLabel:`Open Google Drive`}]}]},{id:`gioi-thieu-tac-gia`,icon:`👤`,title:`About the Author & Purpose`,shortTitle:`Author Info`,keywords:[`quang tu`,`ngo quang tu`,`author`,`lay practitioner`,`pure land`,`dharma sharing`],editorialStatus:`verified`,introduction:[],topics:[{id:`tieu-su-quang-tu`,title:`Lay Practitioner Ngo Quang Tu & Vow of Service`,keywords:[`quang tu`,`biography`,`online monastery`,`free dharma`],blocks:[{type:`paragraph`,text:`I am the lay practitioner Ngộ Quang Từ, usually known as Quang Từ, a child of the Buddha with a deep connection to the Dharma. In my life I have faced many upheavals, adversities and trials that once seemed impossible to overcome. In those dark and difficult moments, my fortunate encounter with the wondrous Dharma helped me gradually understand the profound truths taught by the Buddha, especially an unshakable faith in the law of karma and its consequences. Through years of personal reflection and practice, I have come to see this encounter not as a coincidence within this life, but as the continuation of wholesome roots and connections cultivated over countless past lives.`},{type:`paragraph`,text:`On my path of Buddhist learning and practice, I always hold deep gratitude for the boundless compassion of Kṣitigarbha Bodhisattva of the Great Vow and Avalokiteśvara Bodhisattva of Great Compassion. They have sheltered, illuminated and guided me through difficult times, helping me transform my heart, resolve grievances and rise again after setbacks. From sincere gratitude to the Three Jewels and the great Bodhisattvas, I have made a heartfelt vow to dedicate this humble body and mind to sharing the true Dharma, spreading the light of awakening and the precious teachings of the Buddhas and patriarchs, and nurturing wholesome connections for those seeking a path beyond suffering.`},{type:`paragraph`,text:`I previously had the good fortune to help share the Dharma on Ms. Thạch Mỹ Nghi’s Ngọc Lịch Bửu Phiêu page, sharing lessons on karma, the consequences of good and harmful actions, filial devotion, and practical ways to transform suffering in family and social life. During my dedicated study and spiritual practice, I have had deeply meaningful spiritual experiences that have strengthened my faith in karmic rebirth and the existence of unseen realms within the Dharma realm.`},{type:`paragraph`,text:`Understanding that the demands and temptations of the digital age can draw people into worries, status and gain, leaving them anxious, lonely and lost, I devoted my efforts to creating the Tu Tập Phật Pháp application. It is designed as a dignified, peaceful online practice space where anyone, however busy or far from a temple, can use a phone to practice, bow to the Buddha, recite the Buddha’s name, meditate, copy sutras and listen to Dharma teachings. The application is offered completely free of charge in a spirit of selfless service, with the wish to help people trust deeply in karma, abandon harmful actions, cultivate good deeds, transform karmic tendencies and rediscover inner peace.`},{type:`paragraph`,text:`For the Tu Tập Phật Pháp application to come into being, develop and serve Buddhist practitioners as it does today, I offer my deepest and most sincere gratitude to my wife, Ms. Ôn Nhật Nga, who has stood beside me with understanding, sacrifice and wholehearted support throughout its creation; Mr. Nguyễn Anh Tuấn, Director of Công ty Cổ phần SMOB - SMOB Joint Stock Company, for his dedicated technical expertise and sponsorship of application distribution infrastructure, helping it operate smoothly and reliably on Apple devices (iOS/macOS/iPadOS); Quang Chiến, for his devoted help in building and operating the backend server system and keeping the infrastructure available and secure; Đỗ Chân Đức, for generously providing the rights to include the two valuable works “Sứ Mệnh Độ Vong” and “Sứ Mệnh Thầy Pháp” in the application’s library; and the entire Buddhist community and fellow practitioners near and far who have enthusiastically helped test for errors and contributed valuable feedback during development. I dedicate all merit from creating this application to all beings throughout the Dharma realm, that they may soon enter deeply into the Buddha’s teachings, purify karmic obstacles and become adorned with merit and wisdom. May you and your families enjoy peace in body and mind, auspicious conditions, steadfast bodhicitta and fulfillment in diligent practice on the path to liberation!`},{type:`paragraph`,text:`For questions about the application or the content shared within it, you may contact me directly through the Facebook account or Messenger link below. Thank you sincerely for visiting and accompanying the Tu Tập Phật Pháp application.`},{type:`link`,href:`https://m.me/tranan.buhd`,label:`Message via Messenger`,text:`Connect or ask questions directly via Messenger (m.me/tranan.buhd)`},{type:`link`,href:`https://www.facebook.com/tranan.buhd/`,label:`Personal Facebook Page`,text:`Visit Quang Tu’s Facebook profile (facebook.com/tranan.buhd)`}]}]},{id:`hoi-dap-thuong-gap`,icon:`❓`,title:`Frequently Asked Questions (FAQ)`,shortTitle:`Q & A`,keywords:[`faq`,`working hours`,`menstruation`,`no altar`,`browser data`,`computer`],editorialStatus:`verified`,introduction:[`Quick guidance on common questions regarding daily practice at home and using the app.`],topics:[],faqs:[{id:`faq-ban-di-lam-tu-luc-nao`,question:`I work full-time all day. When is the best time to practice?`,keywords:[`busy`,`work schedule`,`morning`,`evening`],answer:[`Select a time slot you can maintain consistently: before leaving for work, after returning home, or during a quiet evening break. A focused 5–15 minute session daily is far more sustainable than irregular marathon sessions.`],editorialStatus:`verified`},{id:`faq-phu-nu-toi-ngay`,question:`Can women chant sutras or light altar incense during menstruation?`,keywords:[`menstruation`,`incense`,`altar`,`precepts`],answer:[`Yes, absolutely. Menstruation is a natural physiological function, not a moral fault or ritual pollution. Maintain clean attire and practice with a peaceful, respectful mind.`],editorialStatus:`verified`},{id:`faq-khong-co-ban-tho`,question:`Can I chant on the app if I don’t have an altar at home?`,keywords:[`no altar`,`chant at home`,`phone app`],answer:[`Yes. You can recite anywhere that is clean, quiet, and respectful. Sincere reverence directed toward the Buddha in your heart is what truly matters.`],editorialStatus:`verified`},{id:`faq-xoa-trinh-duyet`,question:`Will my cultivation streak be lost if I clear browser cache?`,keywords:[`cache`,`clear data`,`lost data`,`sync`],answer:[`Before clearing app data or switching devices, sign in, connect to the internet and verify that eligible progress has synced. Use Save to account for sutra copies. Downloaded PDFs and audio stay on this device and need to be downloaded again on another device.`],editorialStatus:`verified`},{id:`faq-dung-tren-may-tinh`,question:`Can I use this app on desktop computers and laptops?`,keywords:[`desktop`,`laptop`,`windows`,`mac`,`pwa`],answer:[`Yes. Open the website in a desktop browser to read, listen or practice. If your browser supports installation, follow the website’s installation guide. Phone features such as home-screen widgets depend on the platform.`],editorialStatus:`verified`}]}],o=[{id:`cai-app`,icon:`📱`,label:`Install App`},{id:`dung-web`,icon:`📱`,label:`General Guide`},{id:`doc-sach`,icon:`📖`,label:`Reading`},{id:`cong-cu-tu-tap`,icon:`📿`,label:`Practice Tools`},{id:`phap-thoai`,icon:`🎧`,label:`Dharma Talks`},{id:`tai-khoan-dong-bo`,icon:`☁️`,label:`Cloud Sync`},{id:`huong-dan-nguoi-moi`,icon:`🌱`,label:`Beginners`},{id:`huong-dan-tung-kinh`,icon:`📖`,label:`Sutra Chanting`},{id:`huong-dan-tri-chu`,icon:`📿`,label:`Mantra Recitation`},{id:`tho-tuong-tai-gia`,icon:`🪔`,label:`Altar Setup`},{id:`thuc-hanh-hang-ngay`,icon:`📋`,label:`Daily Practice`},{id:`bo-thi-may-nghe-phap`,icon:`📻`,label:`Dharma Giving`},{id:`gioi-thieu-tac-gia`,icon:`👤`,label:`Author Info`},{id:`hoi-dap-thuong-gap`,icon:`❓`,label:`Q & A`}];export{n as a,r as i,o as n,i as r,a as t};